insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('afcd7304-3779-5a37-9146-cf0a5b6425e9', '5cb5e738-220a-4267-901a-841c834b5d56', '751', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ الْمَقْبُرِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ الْمَسْجِدَ فَدَخَلَ رَجُلٌ فَصَلَّى ثُمَّ جَاءَ فَسَلَّمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَدَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْهِ السَّلَامَ فَقَالَ ‏ ‏ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ فَصَلَّى ثُمَّ جَاءَ فَسَلَّمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ ثَلَاثًا فَقَالَ وَالَّذِي بَعَثَكَ بِالْحَقِّ فَمَا أُحْسِنُ غَيْرَهُ فَعَلِّمْنِي قَالَ إِذَا قُمْتَ إِلَى الصَّلَاةِ فَكَبِّرْ ثُمَّ اقْرَأْ مَا تَيَسَّرَ مَعَكَ مِنْ الْقُرْآنِ ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعًا ثُمَّ ارْفَعْ حَتَّى تَعْتَدِلَ قَائِمًا ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ افْعَلْ ذَلِكَ فِي صَلَاتِكَ كُلِّهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c4a8c6ff-50d7-5efa-8471-30cd892093d8', '5cb5e738-220a-4267-901a-841c834b5d56', '752', '‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي رُكُوعِهِ وَسُجُودِهِ ‏ ‏سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('78952399-1072-573b-9f9c-c71de65e2e79', '5cb5e738-220a-4267-901a-841c834b5d56', '753', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ قَالَ اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَكَعَ وَإِذَا رَفَعَ رَأْسَهُ يُكَبِّرُ وَإِذَا قَامَ مِنْ السَّجْدَتَيْنِ قَالَ اللَّهُ أَكْبَرُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9687a8ea-b331-546d-8bba-1d49b3a90b3c', '5cb5e738-220a-4267-901a-841c834b5d56', '754', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَالَ الْإِمَامُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c368bb8d-9198-523b-be3f-8d11c44a309f', '5cb5e738-220a-4267-901a-841c834b5d56', '755', '‏ ‏بَاب ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ فَضَالَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَأُقَرِّبَنَّ صَلَاةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقْنُتُ ‏ ‏فِي الرَّكْعَةِ الْآخِرَةِ مِنْ صَلَاةِ الظُّهْرِ وَصَلَاةِ الْعِشَاءِ وَصَلَاةِ الصُّبْحِ بَعْدَ مَا يَقُولُ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَيَدْعُو لِلْمُؤْمِنِينَ وَيَلْعَنُ الْكُفَّارَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5ef2ea2f-4715-5001-a004-a884afc51a08', '5cb5e738-220a-4267-901a-841c834b5d56', '756', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي الْأَسْوَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏الْقُنُوتُ فِي الْمَغْرِبِ وَالْفَجْرِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('629cad72-ba24-563d-99a5-1362388ce81e', '5cb5e738-220a-4267-901a-841c834b5d56', '757', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ الْمُجْمِرِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَحْيَى بْنِ خَلَّادٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رِفَاعَةَ بْنِ رَافِعٍ الزُّرَقِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا يَوْمًا نُصَلِّي وَرَاءَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا رَفَعَ رَأْسَهُ مِنْ الرَّكْعَةِ قَالَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ قَالَ رَجُلٌ وَرَاءَهُ رَبَّنَا وَلَكَ الْحَمْدُ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ فَلَمَّا انْصَرَفَ قَالَ مَنْ الْمُتَكَلِّمُ قَالَ أَنَا قَالَ رَأَيْتُ ‏ ‏بِضْعَةً ‏ ‏وَثَلَاثِينَ مَلَكًا ‏ ‏يَبْتَدِرُونَهَا ‏ ‏أَيُّهُمْ يَكْتُبُهَا أَوَّلُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7908ff6c-5e33-54ee-8915-aba0fba1723d', '5cb5e738-220a-4267-901a-841c834b5d56', '758', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ كَانَ ‏ ‏أَنَسٌ ‏ ‏يَنْعَتُ ‏ ‏لَنَا صَلَاةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ ‏ ‏يُصَلِّي وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَامَ حَتَّى نَقُولَ قَدْ نَسِيَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1ba1ab59-f44a-5dba-85ee-ad383addcd37', '5cb5e738-220a-4267-901a-841c834b5d56', '759', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏الْبَرَاءِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رُكُوعُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسُجُودُهُ وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ وَبَيْنَ السَّجْدَتَيْنِ قَرِيبًا مِنْ السَّوَاءِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('baf78f29-d7d1-5468-b0f6-11e55d09fa44', '5cb5e738-220a-4267-901a-841c834b5d56', '760', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ كَانَ ‏ ‏مَالِكُ بْنُ الْحُوَيْرِثِ ‏ ‏يُرِينَا كَيْفَ كَانَ صَلَاةُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَذَاكَ فِي غَيْرِ وَقْتِ صَلَاةٍ فَقَامَ فَأَمْكَنَ الْقِيَامَ ثُمَّ رَكَعَ فَأَمْكَنَ الرُّكُوعَ ثُمَّ رَفَعَ رَأْسَهُ ‏ ‏فَأَنْصَبَ ‏ ‏هُنَيَّةً ‏ ‏قَالَ فَصَلَّى بِنَا صَلَاةَ شَيْخِنَا هَذَا ‏ ‏أَبِي بُرَيْدٍ ‏ ‏وَكَانَ ‏ ‏أَبُو بُرَيْدٍ ‏ ‏إِذَا رَفَعَ رَأْسَهُ مِنْ السَّجْدَةِ الْآخِرَةِ اسْتَوَى قَاعِدًا ثُمَّ نَهَضَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('985f6ef2-558a-5064-b74a-a294122c67d1', '5cb5e738-220a-4267-901a-841c834b5d56', '761', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏وَأَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَانَ يُكَبِّرُ فِي كُلِّ صَلَاةٍ مِنْ الْمَكْتُوبَةِ وَغَيْرِهَا فِي رَمَضَانَ وَغَيْرِهِ فَيُكَبِّرُ حِينَ يَقُومُ ثُمَّ يُكَبِّرُ حِينَ يَرْكَعُ ثُمَّ يَقُولُ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ ثُمَّ يَقُولُ رَبَّنَا وَلَكَ الْحَمْدُ قَبْلَ أَنْ يَسْجُدَ ثُمَّ يَقُولُ اللَّهُ أَكْبَرُ حِينَ يَهْوِي سَاجِدًا ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ مِنْ السُّجُودِ ثُمَّ يُكَبِّرُ حِينَ يَسْجُدُ ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ مِنْ السُّجُودِ ثُمَّ يُكَبِّرُ حِينَ يَقُومُ مِنْ الْجُلُوسِ فِي ‏ ‏الِاثْنَتَيْنِ وَيَفْعَلُ ذَلِكَ فِي كُلِّ رَكْعَةٍ حَتَّى يَفْرُغَ مِنْ الصَّلَاةِ ثُمَّ يَقُولُ حِينَ يَنْصَرِفُ وَالَّذِي نَفْسِي بِيَدِهِ إِنِّي لَأَقْرَبُكُمْ شَبَهًا بِصَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كَانَتْ هَذِهِ لَصَلَاتَهُ حَتَّى فَارَقَ الدُّنْيَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e1b2d90b-0b63-5757-954b-c3eb1e123988', '5cb5e738-220a-4267-901a-841c834b5d56', '762', '‏ ‏قَالَا وَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ يَرْفَعُ رَأْسَهُ يَقُولُ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَبَّنَا وَلَكَ الْحَمْدُ يَدْعُو لِرِجَالٍ فَيُسَمِّيهِمْ بِأَسْمَائِهِمْ فَيَقُولُ اللَّهُمَّ أَنْجِ ‏ ‏الْوَلِيدَ بْنَ الْوَلِيدِ ‏ ‏وَسَلَمَةَ بْنَ هِشَامٍ ‏ ‏وَعَيَّاشَ بْنَ أَبِي رَبِيعَةَ ‏ ‏وَالْمُسْتَضْعَفِينَ مِنْ الْمُؤْمِنِينَ اللَّهُمَّ اشْدُدْ ‏ ‏وَطْأَتَكَ ‏ ‏عَلَى ‏ ‏مُضَرَ ‏ ‏وَاجْعَلْهَا عَلَيْهِمْ ‏ ‏سِنِينَ كَسِنِي ‏ ‏يُوسُفَ ‏ ‏وَأَهْلُ الْمَشْرِقِ يَوْمَئِذٍ مِنْ ‏ ‏مُضَرَ ‏ ‏مُخَالِفُونَ لَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('86a23fe0-5463-5e78-ad47-4d03356cfa65', '5cb5e738-220a-4267-901a-841c834b5d56', '763', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏غَيْرَ مَرَّةٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏سَقَطَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ فَرَسٍ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏سُفْيَانُ ‏ ‏مِنْ فَرَسٍ ‏ ‏فَجُحِشَ ‏ ‏شِقُّهُ الْأَيْمَنُ فَدَخَلْنَا عَلَيْهِ نَعُودُهُ فَحَضَرَتْ الصَّلَاةُ فَصَلَّى بِنَا قَاعِدًا وَقَعَدْنَا ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً صَلَّيْنَا قُعُودًا فَلَمَّا قَضَى الصَّلَاةَ قَالَ إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا رَفَعَ فَارْفَعُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا وَلَكَ الْحَمْدُ وَإِذَا سَجَدَ فَاسْجُدُوا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏كَذَا جَاءَ بِهِ ‏ ‏مَعْمَرٌ ‏ ‏قُلْتُ نَعَمْ قَالَ لَقَدْ حَفِظَ كَذَا ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَلَكَ الْحَمْدُ حَفِظْتُ مِنْ شِقِّهِ الْأَيْمَنِ ‏ ‏فَلَمَّا خَرَجْنَا مِنْ عِنْدِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَأَنَا عِنْدَهُ ‏ ‏فَجُحِشَ ‏ ‏سَاقُهُ الْأَيْمَنُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('693a9ba7-60e9-533a-8e56-41aabcdc2489', '5cb5e738-220a-4267-901a-841c834b5d56', '764', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏وَعَطَاءُ بْنُ يَزِيدَ اللَّيْثِيُّ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُمَا ‏ ‏أَنَّ النَّاسَ قَالُوا يَا رَسُولَ اللَّهِ هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ قَالَ هَلْ ‏ ‏تُمَارُونَ ‏ ‏فِي الْقَمَرِ لَيْلَةَ الْبَدْرِ لَيْسَ دُونَهُ سَحَابٌ قَالُوا لَا يَا رَسُولَ اللَّهِ قَالَ فَهَلْ ‏ ‏تُمَارُونَ ‏ ‏فِي الشَّمْسِ لَيْسَ دُونَهَا سَحَابٌ قَالُوا لَا قَالَ فَإِنَّكُمْ تَرَوْنَهُ كَذَلِكَ يُحْشَرُ النَّاسُ يَوْمَ الْقِيَامَةِ فَيَقُولُ مَنْ كَانَ يَعْبُدُ شَيْئًا فَلْيَتَّبِعْ فَمِنْهُمْ مَنْ يَتَّبِعُ الشَّمْسَ وَمِنْهُمْ مَنْ يَتَّبِعُ الْقَمَرَ وَمِنْهُمْ مَنْ يَتَّبِعُ ‏ ‏الطَّوَاغِيتَ ‏ ‏وَتَبْقَى هَذِهِ الْأُمَّةُ فِيهَا مُنَافِقُوهَا ‏ ‏فَيَأْتِيهِمْ اللَّهُ فَيَقُولُ أَنَا رَبُّكُمْ فَيَقُولُونَ هَذَا مَكَانُنَا حَتَّى يَأْتِيَنَا رَبُّنَا فَإِذَا جَاءَ رَبُّنَا عَرَفْنَاهُ ‏ ‏فَيَأْتِيهِمْ اللَّهُ فَيَقُولُ ‏ ‏أَنَا رَبُّكُمْ فَيَقُولُونَ أَنْتَ رَبُّنَا فَيَدْعُوهُمْ فَيُضْرَبُ الصِّرَاطُ بَيْنَ ظَهْرَانَيْ جَهَنَّمَ فَأَكُونُ أَوَّلَ مَنْ يَجُوزُ مِنْ الرُّسُلِ بِأُمَّتِهِ وَلَا يَتَكَلَّمُ يَوْمَئِذٍ أَحَدٌ إِلَّا الرُّسُلُ وَكَلَامُ الرُّسُلِ يَوْمَئِذٍ اللَّهُمَّ سَلِّمْ سَلِّمْ وَفِي جَهَنَّمَ ‏ ‏كَلَالِيبُ ‏ ‏مِثْلُ ‏ ‏شَوْكِ السَّعْدَانِ ‏ ‏هَلْ رَأَيْتُمْ ‏ ‏شَوْكَ السَّعْدَانِ ‏ ‏قَالُوا نَعَمْ قَالَ فَإِنَّهَا مِثْلُ ‏ ‏شَوْكِ السَّعْدَانِ ‏ ‏غَيْرَ أَنَّهُ لَا يَعْلَمُ قَدْرَ عِظَمِهَا إِلَّا اللَّهُ تَخْطَفُ النَّاسَ بِأَعْمَالِهِمْ فَمِنْهُمْ مَنْ ‏ ‏يُوبَقُ ‏ ‏بِعَمَلِهِ وَمِنْهُمْ مَنْ ‏ ‏يُخَرْدَلُ ‏ ‏ثُمَّ يَنْجُو حَتَّى إِذَا أَرَادَ اللَّهُ رَحْمَةَ مَنْ أَرَادَ مِنْ أَهْلِ النَّارِ أَمَرَ اللَّهُ الْمَلَائِكَةَ أَنْ يُخْرِجُوا مَنْ كَانَ يَعْبُدُ اللَّهَ فَيُخْرِجُونَهُمْ وَيَعْرِفُونَهُمْ بِآثَارِ السُّجُودِ وَحَرَّمَ اللَّهُ عَلَى النَّارِ أَنْ تَأْكُلَ أَثَرَ السُّجُودِ فَيَخْرُجُونَ مِنْ النَّارِ فَكُلُّ ابْنِ ‏ ‏آدَمَ ‏ ‏تَأْكُلُهُ النَّارُ إِلَّا أَثَرَ السُّجُودِ فَيَخْرُجُونَ مِنْ النَّارِ قَدْ ‏ ‏امْتَحَشُوا ‏ ‏فَيُصَبُّ عَلَيْهِمْ مَاءُ الْحَيَاةِ فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي ‏ ‏حَمِيلِ السَّيْلِ ‏ ‏ثُمَّ يَفْرُغُ اللَّهُ مِنْ الْقَضَاءِ بَيْنَ الْعِبَادِ وَيَبْقَى رَجُلٌ بَيْنَ الْجَنَّةِ وَالنَّارِ وَهُوَ آخِرُ أَهْلِ النَّارِ دُخُولًا الْجَنَّةَ مُقْبِلٌ بِوَجْهِهِ قِبَلَ النَّارِ فَيَقُولُ يَا رَبِّ اصْرِفْ وَجْهِي عَنْ النَّارِ قَدْ ‏ ‏قَشَبَنِي ‏ ‏رِيحُهَا وَأَحْرَقَنِي ‏ ‏ذَكَاؤُهَا ‏ ‏فَيَقُولُ هَلْ عَسَيْتَ إِنْ فُعِلَ ذَلِكَ بِكَ أَنْ تَسْأَلَ غَيْرَ ذَلِكَ فَيَقُولُ لَا وَعِزَّتِكَ فَيُعْطِي اللَّهَ مَا يَشَاءُ مِنْ عَهْدٍ وَمِيثَاقٍ فَيَصْرِفُ اللَّهُ وَجْهَهُ عَنْ النَّارِ فَإِذَا أَقْبَلَ بِهِ عَلَى الْجَنَّةِ رَأَى ‏ ‏بَهْجَتَهَا ‏ ‏سَكَتَ مَا شَاءَ اللَّهُ أَنْ يَسْكُتَ ثُمَّ قَالَ يَا رَبِّ قَدِّمْنِي عِنْدَ بَابِ الْجَنَّةِ فَيَقُولُ اللَّهُ لَهُ أَلَيْسَ قَدْ أَعْطَيْتَ الْعُهُودَ وَالْمِيثَاقَ أَنْ لَا تَسْأَلَ غَيْرَ الَّذِي كُنْتَ سَأَلْتَ فَيَقُولُ يَا رَبِّ لَا أَكُونُ أَشْقَى خَلْقِكَ فَيَقُولُ فَمَا عَسَيْتَ إِنْ أُعْطِيتَ ذَلِكَ أَنْ لَا تَسْأَلَ غَيْرَهُ فَيَقُولُ لَا وَعِزَّتِكَ لَا أَسْأَلُ غَيْرَ ذَلِكَ فَيُعْطِي رَبَّهُ مَا شَاءَ مِنْ عَهْدٍ وَمِيثَاقٍ فَيُقَدِّمُهُ إِلَى بَابِ الْجَنَّةِ فَإِذَا بَلَغَ بَابَهَا فَرَأَى زَهْرَتَهَا وَمَا فِيهَا مِنْ النَّضْرَةِ وَالسُّرُورِ فَيَسْكُتُ مَا شَاءَ اللَّهُ أَنْ يَسْكُتَ فَيَقُولُ يَا رَبِّ أَدْخِلْنِي الْجَنَّةَ فَيَقُولُ اللَّهُ ‏ ‏وَيْحَكَ ‏ ‏يَا ابْنَ ‏ ‏آدَمَ ‏ ‏مَا أَغْدَرَكَ أَلَيْسَ قَدْ أَعْطَيْتَ الْعُهُودَ وَالْمِيثَاقَ أَنْ لَا تَسْأَلَ غَيْرَ الَّذِي أُعْطِيتَ فَيَقُولُ يَا رَبِّ لَا تَجْعَلْنِي أَشْقَى خَلْقِكَ فَيَضْحَكُ اللَّهُ عَزَّ وَجَلَّ مِنْهُ ثُمَّ يَأْذَنُ لَهُ فِي دُخُولِ الْجَنَّةِ فَيَقُولُ تَمَنَّ فَيَتَمَنَّى حَتَّى إِذَا انْقَطَعَ أُمْنِيَّتُهُ قَالَ اللَّهُ عَزَّ وَجَلَّ مِنْ كَذَا وَكَذَا أَقْبَلَ يُذَكِّرُهُ رَبُّهُ حَتَّى إِذَا انْتَهَتْ بِهِ الْأَمَانِيُّ قَالَ اللَّهُ تَعَالَى لَكَ ذَلِكَ وَمِثْلُهُ مَعَهُ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ اللَّهُ لَكَ ذَلِكَ وَعَشَرَةُ أَمْثَالِهِ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏لَمْ أَحْفَظْ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا قَوْلَهُ لَكَ ذَلِكَ وَمِثْلُهُ مَعَهُ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏إِنِّي سَمِعْتُهُ يَقُولُ ذَلِكَ لَكَ وَعَشَرَةُ أَمْثَالِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c189783c-d7cc-508e-a37b-9d12c01adf60', '5cb5e738-220a-4267-901a-841c834b5d56', '765', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏ابْنِ هُرْمُزَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَالِكٍ ابْنِ بُحَيْنَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا صَلَّى ‏ ‏فَرَجَ ‏ ‏بَيْنَ يَدَيْهِ ‏ ‏حَتَّى يَبْدُوَ بَيَاضُ إِبْطَيْهِ ‏ ‏وَقَالَ ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ رَبِيعَةَ ‏ ‏نَحْوَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('11f242c0-344e-5dd1-95f4-a348e6d79000', '5cb5e738-220a-4267-901a-841c834b5d56', '766', '‏ ‏حَدَّثَنَا ‏ ‏الصَّلْتُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏وَاصِلٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏رَأَى رَجُلًا لَا يُتِمُّ رُكُوعَهُ وَلَا سُجُودَهُ فَلَمَّا قَضَى صَلَاتَهُ قَالَ لَهُ ‏ ‏حُذَيْفَةُ ‏ ‏مَا صَلَّيْتَ قَالَ وَأَحْسِبُهُ قَالَ وَلَوْ مُتَّ مُتَّ عَلَى غَيْرِ سُنَّةِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f444c129-a7a5-5541-b588-36dad5f5224d', '5cb5e738-220a-4267-901a-841c834b5d56', '767', '‏ ‏حَدَّثَنَا ‏ ‏قَبِيصَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أُمِرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَسْجُدَ عَلَى سَبْعَةِ أَعْضَاءٍ ‏ ‏وَلَا يَكُفَّ ‏ ‏شَعَرًا وَلَا ثَوْبًا الْجَبْهَةِ وَالْيَدَيْنِ وَالرُّكْبَتَيْنِ وَالرِّجْلَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5d7580dc-44d4-50d3-a989-8565f5c11af3', '5cb5e738-220a-4267-901a-841c834b5d56', '768', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُمِرْنَا أَنْ نَسْجُدَ عَلَى سَبْعَةِ أَعْظُمٍ ‏ ‏وَلَا نَكُفَّ ‏ ‏ثَوْبًا وَلَا شَعَرًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c6314019-0235-5dd4-84e7-f5c2fa1744fd', '5cb5e738-220a-4267-901a-841c834b5d56', '769', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ الْخَطْمِيِّ ‏ ‏حَدَّثَنَا ‏ ‏الْبَرَاءُ بْنُ عَازِبٍ ‏ ‏وَهُوَ غَيْرُ كَذُوبٍ ‏ ‏قَالَ ‏ ‏كُنَّا نُصَلِّي خَلْفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا قَالَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ لَمْ ‏ ‏يَحْنِ ‏ ‏أَحَدٌ مِنَّا ظَهْرَهُ حَتَّى يَضَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَبْهَتَهُ عَلَى الْأَرْضِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('39d8e263-a9df-57eb-be50-d9ef3589ef58', '5cb5e738-220a-4267-901a-841c834b5d56', '770', '‏ ‏حَدَّثَنَا ‏ ‏مُعَلَّى بْنُ أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ أَسْجُدَ عَلَى سَبْعَةِ أَعْظُمٍ عَلَى الْجَبْهَةِ وَأَشَارَ بِيَدِهِ عَلَى أَنْفِهِ وَالْيَدَيْنِ وَالرُّكْبَتَيْنِ وَأَطْرَافِ الْقَدَمَيْنِ ‏ ‏وَلَا نَكْفِتَ ‏ ‏الثِّيَابَ وَالشَّعَرَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0d380e9a-a627-5d79-b55a-eda912127f7e', '5cb5e738-220a-4267-901a-841c834b5d56', '771', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ إِلَى ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏فَقُلْتُ أَلَا تَخْرُجُ بِنَا إِلَى النَّخْلِ نَتَحَدَّثُ فَخَرَجَ فَقَالَ قُلْتُ حَدِّثْنِي مَا سَمِعْتَ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي لَيْلَةِ الْقَدْرِ قَالَ اعْتَكَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشْرَ الْأُوَلِ مِنْ رَمَضَانَ وَاعْتَكَفْنَا مَعَهُ فَأَتَاهُ ‏ ‏جِبْرِيلُ ‏ ‏فَقَالَ إِنَّ الَّذِي تَطْلُبُ أَمَامَكَ فَاعْتَكَفَ الْعَشْرَ الْأَوْسَطَ فَاعْتَكَفْنَا مَعَهُ فَأَتَاهُ ‏ ‏جِبْرِيلُ ‏ ‏فَقَالَ إِنَّ الَّذِي تَطْلُبُ أَمَامَكَ فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطِيبًا صَبِيحَةَ عِشْرِينَ مِنْ رَمَضَانَ فَقَالَ ‏ ‏مَنْ كَانَ اعْتَكَفَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلْيَرْجِعْ فَإِنِّي أُرِيتُ لَيْلَةَ الْقَدْرِ وَإِنِّي نُسِّيتُهَا وَإِنَّهَا فِي الْعَشْرِ الْأَوَاخِرِ فِي ‏ ‏وِتْرٍ ‏ ‏وَإِنِّي رَأَيْتُ كَأَنِّي أَسْجُدُ فِي طِينٍ وَمَاءٍ وَكَانَ سَقْفُ الْمَسْجِدِ جَرِيدَ النَّخْلِ وَمَا نَرَى فِي السَّمَاءِ شَيْئًا فَجَاءَتْ ‏ ‏قَزْعَةٌ ‏ ‏فَأُمْطِرْنَا فَصَلَّى بِنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى رَأَيْتُ أَثَرَ الطِّينِ وَالْمَاءِ عَلَى جَبْهَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَرْنَبَتِهِ ‏ ‏تَصْدِيقَ رُؤْيَاهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8ff37a3e-f73f-563e-8c6a-baf041441da0', '5cb5e738-220a-4267-901a-841c834b5d56', '772', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّاسُ يُصَلُّونَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُمْ عَاقِدُوا أُزْرِهِمْ مِنْ الصِّغَرِ عَلَى رِقَابِهِمْ فَقِيلَ لِلنِّسَاءِ ‏ ‏لَا تَرْفَعْنَ رُءُوسَكُنَّ حَتَّى يَسْتَوِيَ الرِّجَالُ جُلُوسًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8435037d-1122-5847-abf7-75cd66a48106', '5cb5e738-220a-4267-901a-841c834b5d56', '773', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ وَهْوَ ابْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أُمِرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَسْجُدَ عَلَى سَبْعَةِ أَعْظُمٍ ‏ ‏وَلَا يَكُفَّ ‏ ‏ثَوْبَهُ وَلَا شَعَرَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('512d9d17-cdd4-5442-9978-f9620f17afa4', '5cb5e738-220a-4267-901a-841c834b5d56', '774', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُمِرْتُ أَنْ أَسْجُدَ عَلَى سَبْعَةٍ لَا أَكُفُّ شَعَرًا وَلَا ثَوْبًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('95b6fd6d-63d9-56e2-9179-19469454073a', '5cb5e738-220a-4267-901a-841c834b5d56', '775', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْصُورُ بْنُ الْمُعْتَمِرِ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ هُوَ ابْنُ صُبَيْحٍ أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ أَنْ يَقُولَ فِي رُكُوعِهِ وَسُجُودِهِ ‏ ‏سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي يَتَأَوَّلُ الْقُرْآنَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dbd6f0a0-6c4a-5225-a2a3-aa3a85008373', '5cb5e738-220a-4267-901a-841c834b5d56', '776', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏أَنَّ ‏ ‏مَالِكَ بْنَ الْحُوَيْرِثِ ‏ ‏قَالَ لِأَصْحَابِهِ ‏ ‏أَلَا أُنَبِّئُكُمْ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَذَاكَ فِي غَيْرِ حِينِ صَلَاةٍ ‏ ‏فَقَامَ ثُمَّ رَكَعَ فَكَبَّرَ ثُمَّ رَفَعَ رَأْسَهُ فَقَامَ ‏ ‏هُنَيَّةً ‏ ‏ثُمَّ سَجَدَ ثُمَّ رَفَعَ رَأْسَهُ ‏ ‏هُنَيَّةً ‏ ‏فَصَلَّى صَلَاةَ ‏ ‏عَمْرِو بْنِ سَلِمَةَ ‏ ‏شَيْخِنَا هَذَا قَالَ ‏ ‏أَيُّوبُ ‏ ‏كَانَ يَفْعَلُ شَيْئًا لَمْ أَرَهُمْ يَفْعَلُونَهُ كَانَ يَقْعُدُ فِي الثَّالِثَةِ وَالرَّابِعَةِ ‏ ‏قَالَ فَأَتَيْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَقَمْنَا عِنْدَهُ فَقَالَ لَوْ رَجَعْتُمْ إِلَى أَهْلِيكُمْ صَلُّوا صَلَاةَ كَذَا فِي حِينِ كَذَا صَلُّوا صَلَاةَ كَذَا فِي حِينِ كَذَا فَإِذَا حَضَرَتْ الصَّلَاةُ فَلْيُؤَذِّنْ أَحَدُكُمْ وَلْيَؤُمَّكُمْ أَكْبَرُكُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6575a640-3d98-546a-bc63-f2bfd8acb76f', '5cb5e738-220a-4267-901a-841c834b5d56', '777', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الزُّبَيْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ ‏ ‏كَانَ سُجُودُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرُكُوعُهُ وَقُعُودُهُ بَيْنَ السَّجْدَتَيْنِ قَرِيبًا مِنْ السَّوَاءِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a110c2b4-0e92-5e65-a074-de2addb89865', '5cb5e738-220a-4267-901a-841c834b5d56', '778', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏إِنِّي لَا ‏ ‏آلُو ‏ ‏أَنْ أُصَلِّيَ بِكُمْ كَمَا رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِنَا قَالَ ‏ ‏ثَابِتٌ ‏ ‏كَانَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏يَصْنَعُ شَيْئًا لَمْ أَرَكُمْ تَصْنَعُونَهُ كَانَ ‏ ‏إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَامَ حَتَّى يَقُولَ الْقَائِلُ قَدْ نَسِيَ وَبَيْنَ السَّجْدَتَيْنِ حَتَّى يَقُولَ الْقَائِلُ قَدْ نَسِيَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('de1cbc43-6bda-5673-9796-7e9d80cc1b90', '5cb5e738-220a-4267-901a-841c834b5d56', '779', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اعْتَدِلُوا فِي السُّجُودِ وَلَا يَبْسُطْ أَحَدُكُمْ ذِرَاعَيْهِ انْبِسَاطَ الْكَلْبِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8fc22836-c913-590b-b589-d8dfd8178cab', '5cb5e738-220a-4267-901a-841c834b5d56', '780', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ الْحُوَيْرِثِ اللَّيْثِيُّ ‏ ‏أَنَّهُ ‏ ‏رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فَإِذَا كَانَ فِي ‏ ‏وِتْرٍ ‏ ‏مِنْ صَلَاتِهِ لَمْ يَنْهَضْ حَتَّى يَسْتَوِيَ قَاعِدًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('745637c7-af1f-53cc-973e-bbb610f22382', '5cb5e738-220a-4267-901a-841c834b5d56', '781', '‏ ‏حَدَّثَنَا ‏ ‏مُعَلَّى بْنُ أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ جَاءَنَا ‏ ‏مَالِكُ بْنُ الْحُوَيْرِثِ ‏ ‏فَصَلَّى بِنَا فِي مَسْجِدِنَا هَذَا فَقَالَ إِنِّي لَأُصَلِّي بِكُمْ وَمَا أُرِيدُ الصَّلَاةَ وَلَكِنْ أُرِيدُ أَنْ أُرِيَكُمْ ‏ ‏كَيْفَ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَالَ ‏ ‏أَيُّوبُ ‏ ‏فَقُلْتُ ‏ ‏لِأَبِي قِلَابَةَ ‏ ‏وَكَيْفَ كَانَتْ صَلَاتُهُ قَالَ مِثْلَ صَلَاةِ شَيْخِنَا هَذَا ‏ ‏يَعْنِي ‏ ‏عَمْرَو بْنَ سَلِمَةَ ‏ ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏وَكَانَ ذَلِكَ الشَّيْخُ يُتِمُّ التَّكْبِيرَ وَإِذَا رَفَعَ رَأْسَهُ عَنْ السَّجْدَةِ الثَّانِيَةِ جَلَسَ وَاعْتَمَدَ عَلَى الْأَرْضِ ثُمَّ قَامَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9b0a8f73-e596-5c8f-9812-daca8fd1371f', '5cb5e738-220a-4267-901a-841c834b5d56', '782', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ صَالِحٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُلَيْحُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏صَلَّى لَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَجَهَرَ بِالتَّكْبِيرِ حِينَ رَفَعَ رَأْسَهُ مِنْ السُّجُودِ وَحِينَ سَجَدَ وَحِينَ رَفَعَ وَحِينَ قَامَ مِنْ الرَّكْعَتَيْنِ وَقَالَ هَكَذَا رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eb1510b7-664f-5b57-a1f8-3552d8458478', '5cb5e738-220a-4267-901a-841c834b5d56', '783', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏غَيْلَانُ بْنُ جَرِيرٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ أَنَا ‏ ‏وَعِمْرَانُ ‏ ‏صَلَاةً خَلْفَ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَكَانَ إِذَا سَجَدَ كَبَّرَ وَإِذَا رَفَعَ كَبَّرَ وَإِذَا نَهَضَ مِنْ الرَّكْعَتَيْنِ كَبَّرَ فَلَمَّا سَلَّمَ أَخَذَ ‏ ‏عِمْرَانُ ‏ ‏بِيَدِي فَقَالَ لَقَدْ صَلَّى بِنَا هَذَا صَلَاةَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ لَقَدْ ذَكَّرَنِي هَذَا صَلَاةَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9dc0f809-55b0-553e-b8c5-ae2fe259437a', '5cb5e738-220a-4267-901a-841c834b5d56', '784', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّهُ كَانَ يَرَى ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏يَتَرَبَّعُ فِي الصَّلَاةِ إِذَا جَلَسَ فَفَعَلْتُهُ وَأَنَا يَوْمَئِذٍ حَدِيثُ السِّنِّ فَنَهَانِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏وَقَالَ إِنَّمَا سُنَّةُ الصَّلَاةِ أَنْ تَنْصِبَ رِجْلَكَ الْيُمْنَى وَتَثْنِيَ الْيُسْرَى فَقُلْتُ إِنَّكَ تَفْعَلُ ذَلِكَ فَقَالَ إِنَّ رِجْلَيَّ لَا تَحْمِلَانِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d01c8cf0-135f-578c-b03e-e0dca39248f9', '5cb5e738-220a-4267-901a-841c834b5d56', '785', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ حَلْحَلَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏وَحَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏وَيَزِيدَ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ حَلْحَلَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏أَنَّهُ كَانَ جَالِسًا مَعَ نَفَرٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْنَا صَلَاةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَبُو حُمَيْدٍ السَّاعِدِيُّ ‏ ‏أَنَا كُنْتُ أَحْفَظَكُمْ لِصَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَيْتُهُ إِذَا كَبَّرَ جَعَلَ يَدَيْهِ ‏ ‏حِذَاءَ ‏ ‏مَنْكِبَيْهِ ‏ ‏وَإِذَا رَكَعَ أَمْكَنَ يَدَيْهِ مِنْ رُكْبَتَيْهِ ثُمَّ ‏ ‏هَصَرَ ‏ ‏ظَهْرَهُ فَإِذَا رَفَعَ رَأْسَهُ اسْتَوَى حَتَّى يَعُودَ كُلُّ ‏ ‏فَقَارٍ ‏ ‏مَكَانَهُ فَإِذَا سَجَدَ وَضَعَ يَدَيْهِ غَيْرَ مُفْتَرِشٍ وَلَا قَابِضِهِمَا وَاسْتَقْبَلَ بِأَطْرَافِ أَصَابِعِ رِجْلَيْهِ الْقِبْلَةَ فَإِذَا جَلَسَ فِي الرَّكْعَتَيْنِ جَلَسَ عَلَى رِجْلِهِ الْيُسْرَى وَنَصَبَ الْيُمْنَى وَإِذَا جَلَسَ فِي الرَّكْعَةِ الْآخِرَةِ قَدَّمَ رِجْلَهُ الْيُسْرَى وَنَصَبَ الْأُخْرَى وَقَعَدَ عَلَى مَقْعَدَتِهِ ‏ ‏وَسَمِعَ ‏ ‏اللَّيْثُ ‏ ‏يَزِيدَ بْنَ أَبِي حَبِيبٍ ‏ ‏وَيَزِيدُ ‏ ‏مِنْ ‏ ‏مُحَمَّدِ بْنِ حَلْحَلَةَ ‏ ‏وَابْنُ حَلْحَلَةَ ‏ ‏مِنْ ‏ ‏ابْنِ عَطَاءٍ ‏ ‏قَالَ ‏ ‏أَبُو صَالِحٍ ‏ ‏عَنْ ‏ ‏اللَّيْثِ ‏ ‏كُلُّ فَقَارٍ ‏ ‏وَقَالَ ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ عَمْرٍو ‏ ‏حَدَّثَهُ ‏ ‏كُلُّ فَقَارٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0dcefd1c-8a5c-57d5-acc0-6b4ffb942810', '5cb5e738-220a-4267-901a-841c834b5d56', '786', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ هُرْمُزَ ‏ ‏مَوْلَى ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً مَوْلَى ‏ ‏رَبِيعَةَ بْنِ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ ابْنَ بُحَيْنَةَ ‏ ‏وَهُوَ مِنْ ‏ ‏أَزْدِ شَنُوءَةَ ‏ ‏وَهُوَ حَلِيفٌ ‏ ‏لِبَنِي عَبْدِ مَنَافٍ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى بِهِمْ الظَّهْرَ فَقَامَ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ لَمْ يَجْلِسْ فَقَامَ النَّاسُ مَعَهُ حَتَّى إِذَا قَضَى الصَّلَاةَ وَانْتَظَرَ النَّاسُ تَسْلِيمَهُ كَبَّرَ وَهُوَ جَالِسٌ فَسَجَدَ سَجْدَتَيْنِ قَبْلَ أَنْ يُسَلِّمَ ثُمَّ سَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d91046cc-5440-56b7-80a2-103da372a114', '5cb5e738-220a-4267-901a-841c834b5d56', '787', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَكْرٌ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَالِكٍ ابْنِ بُحَيْنَةَ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ فَقَامَ وَعَلَيْهِ جُلُوسٌ فَلَمَّا كَانَ فِي آخِرِ صَلَاتِهِ سَجَدَ سَجْدَتَيْنِ وَهُوَ جَالِسٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ae2be7f1-f994-5d09-9bb0-3549cf7f3c23', '5cb5e738-220a-4267-901a-841c834b5d56', '788', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقِ بْنِ سَلَمَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏كُنَّا إِذَا صَلَّيْنَا خَلْفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْنَا السَّلَامُ عَلَى ‏ ‏جِبْرِيلَ ‏ ‏وَمِيكَائِيلَ ‏ ‏السَّلَامُ عَلَى فُلَانٍ وَفُلَانٍ فَالْتَفَتَ إِلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ هُوَ السَّلَامُ فَإِذَا صَلَّى أَحَدُكُمْ فَلْيَقُلْ التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ فَإِنَّكُمْ إِذَا قُلْتُمُوهَا أَصَابَتْ كُلَّ عَبْدٍ لِلَّهِ صَالِحٍ فِي السَّمَاءِ وَالْأَرْضِ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e28559dd-f0ab-54de-b8a5-2829cb95b30c', '5cb5e738-220a-4267-901a-841c834b5d56', '789', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَدْعُو فِي الصَّلَاةِ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَأَعُوذُ بِكَ مِنْ فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَفِتْنَةِ الْمَمَاتِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْمَأْثَمِ ‏ ‏وَالْمَغْرَمِ ‏ ‏فَقَالَ لَهُ قَائِلٌ مَا أَكْثَرَ مَا تَسْتَعِيذُ مِنْ ‏ ‏الْمَغْرَمِ ‏ ‏فَقَالَ إِنَّ الرَّجُلَ إِذَا ‏ ‏غَرِمَ ‏ ‏حَدَّثَ فَكَذَبَ وَوَعَدَ فَأَخْلَفَ ‏ ‏وَعَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَعِيذُ فِي صَلَاتِهِ مِنْ فِتْنَةِ ‏ ‏الدَّجَّالِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('721dcd35-a8b1-5af8-9c0a-44d69c07eac6', '5cb5e738-220a-4267-901a-841c834b5d56', '790', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ قَالَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِّمْنِي دُعَاءً أَدْعُو بِهِ فِي صَلَاتِي قَالَ قُلْ ‏ ‏اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي إِنَّك أَنْتَ الْغَفُورُ الرَّحِيمُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b9146eab-589c-5144-b234-f0b9c0d4d42b', '5cb5e738-220a-4267-901a-841c834b5d56', '791', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏حَدَّثَنِي ‏ ‏شَقِيقٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا إِذَا كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الصَّلَاةِ قُلْنَا السَّلَامُ عَلَى اللَّهِ مِنْ عِبَادِهِ السَّلَامُ عَلَى فُلَانٍ وَفُلَانٍ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُولُوا السَّلَامُ عَلَى اللَّهِ فَإِنَّ اللَّهَ هُوَ السَّلَامُ وَلَكِنْ قُولُوا التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ فَإِنَّكُمْ إِذَا قُلْتُمْ أَصَابَ كُلَّ عَبْدٍ فِي السَّمَاءِ أَوْ بَيْنَ السَّمَاءِ وَالْأَرْضِ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ثُمَّ يَتَخَيَّرُ مِنْ الدُّعَاءِ أَعْجَبَهُ إِلَيْهِ فَيَدْعُو ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('65072611-04af-5788-983a-8df169204993', '5cb5e738-220a-4267-901a-841c834b5d56', '792', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ سَأَلْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏فَقَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ فِي الْمَاءِ وَالطِّينِ حَتَّى رَأَيْتُ أَثَرَ الطِّينِ فِي جَبْهَتِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1d74a2cc-75be-5aec-9e57-c9b5a6c594d3', '5cb5e738-220a-4267-901a-841c834b5d56', '793', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏هِنْدٍ بِنْتِ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَلَّمَ قَامَ النِّسَاءُ حِينَ يَقْضِي تَسْلِيمَهُ وَمَكَثَ يَسِيرًا قَبْلَ أَنْ يَقُومَ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏فَأُرَى وَاللَّهُ أَعْلَمُ أَنَّ مُكْثَهُ لِكَيْ ‏ ‏يَنْفُذَ ‏ ‏النِّسَاءُ قَبْلَ أَنْ يُدْرِكَهُنَّ مَنْ انْصَرَفَ مِنْ الْقَوْمِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9fbac8f3-54de-599f-b75d-1c6d27e43482', '5cb5e738-220a-4267-901a-841c834b5d56', '794', '‏ ‏حَدَّثَنَا ‏ ‏حِبَّانُ بْنُ مُوسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏عِتْبَانَ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏صَلَّيْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمْنَا حِينَ سَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('37509be1-0b3b-5b7f-9927-2c6dfe0aa2c0', '5cb5e738-220a-4267-901a-841c834b5d56', '795', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدَانُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَحْمُودُ بْنُ الرَّبِيعِ ‏ ‏وَزَعَمَ أَنَّهُ عَقَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَقَلَ ‏ ‏مَجَّةً ‏ ‏مَجَّهَا مِنْ دَلْوٍ كَانَ فِي دَارِهِمْ قَالَ سَمِعْتُ ‏ ‏عِتْبَانَ بْنَ مَالِكٍ الْأَنْصارِيَّ ‏ ‏ثُمَّ ‏ ‏أَحَدَ ‏ ‏بَنِي سَالِمٍ ‏ ‏قَالَ كُنْتُ أُصَلِّي لِقَوْمِي ‏ ‏بَنِي سَالِمٍ ‏ ‏فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنِّي ‏ ‏أَنْكَرْتُ ‏ ‏بَصَرِي وَإِنَّ السُّيُولَ تَحُولُ بَيْنِي وَبَيْنَ مَسْجِدِ قَوْمِي فَلَوَدِدْتُ أَنَّكَ جِئْتَ فَصَلَّيْتَ فِي بَيْتِي مَكَانًا حَتَّى أَتَّخِذَهُ مَسْجِدًا فَقَالَ ‏ ‏أَفْعَلُ إِنْ شَاءَ اللَّهُ فَغَدَا عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏مَعَهُ بَعْدَ مَا اشْتَدَّ النَّهَارُ فَاسْتَأْذَنَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَذِنْتُ لَهُ فَلَمْ يَجْلِسْ حَتَّى قَالَ أَيْنَ تُحِبُّ أَنْ أُصَلِّيَ مِنْ بَيْتِكَ فَأَشَارَ إِلَيْهِ مِنْ الْمَكَانِ الَّذِي أَحَبَّ أَنْ يُصَلِّيَ فِيهِ فَقَامَ فَصَفَفْنَا خَلْفَهُ ثُمَّ سَلَّمَ وَسَلَّمْنَا حِينَ سَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3b5a6f4c-60ec-52eb-8490-8737200ba80a', '5cb5e738-220a-4267-901a-841c834b5d56', '796', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ نَصْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏أَنَّ ‏ ‏أَبَا مَعْبَدٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَفْعَ الصَّوْتِ بِالذِّكْرِ حِينَ يَنْصَرِفُ النَّاسُ مِنْ الْمَكْتُوبَةِ كَانَ عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏كُنْتُ أَعْلَمُ إِذَا انْصَرَفُوا بِذَلِكَ إِذَا سَمِعْتُهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2db7f325-1e9f-5e34-97c8-5086afbd60e7', '5cb5e738-220a-4267-901a-841c834b5d56', '797', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرٌو ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو مَعْبَدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏كُنْتُ أَعْرِفُ انْقِضَاءَ صَلَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالتَّكْبِيرِ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏قَالَ كَانَ ‏ ‏أَبُو مَعْبَدٍ ‏ ‏أَصْدَقَ مَوَالِي ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏وَاسْمُهُ ‏ ‏نَافِذٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('15941847-d792-5d83-bd07-4d1253830697', '5cb5e738-220a-4267-901a-841c834b5d56', '798', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏جَاءَ الْفُقَرَاءُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا ذَهَبَ أَهْلُ ‏ ‏الدُّثُورِ ‏ ‏مِنْ الْأَمْوَالِ بِالدَّرَجَاتِ الْعُلَا وَالنَّعِيمِ الْمُقِيمِ يُصَلُّونَ كَمَا نُصَلِّي وَيَصُومُونَ كَمَا نَصُومُ وَلَهُمْ فَضْلٌ مِنْ أَمْوَالٍ يَحُجُّونَ بِهَا وَيَعْتَمِرُونَ وَيُجَاهِدُونَ وَيَتَصَدَّقُونَ قَالَ ‏ ‏أَلَا أُحَدِّثُكُمْ إِنْ أَخَذْتُمْ أَدْرَكْتُمْ مَنْ سَبَقَكُمْ وَلَمْ يُدْرِكْكُمْ أَحَدٌ بَعْدَكُمْ وَكُنْتُمْ خَيْرَ مَنْ أَنْتُمْ بَيْنَ ‏ ‏ظَهْرَانَيْهِ ‏ ‏إِلَّا مَنْ عَمِلَ مِثْلَهُ تُسَبِّحُونَ وَتَحْمَدُونَ وَتُكَبِّرُونَ خَلْفَ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ فَاخْتَلَفْنَا بَيْنَنَا فَقَالَ بَعْضُنَا نُسَبِّحُ ثَلَاثًا وَثَلَاثِينَ وَنَحْمَدُ ثَلَاثًا وَثَلَاثِينَ وَنُكَبِّرُ أَرْبَعًا وَثَلَاثِينَ فَرَجَعْتُ إِلَيْهِ فَقَالَ تَقُولُ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَاللَّهُ أَكْبَرُ حَتَّى يَكُونَ مِنْهُنَّ كُلِّهِنَّ ثَلَاثًا وَثَلَاثِينَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('45b8f7e7-2a67-5690-9408-11c775bf3d1d', '5cb5e738-220a-4267-901a-841c834b5d56', '799', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏وَرَّادٍ ‏ ‏كَاتِبِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ أَمْلَى عَلَيَّ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏فِي كِتَابٍ إِلَى ‏ ‏مُعَاوِيَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي ‏ ‏دُبُرِ ‏ ‏كُلِّ صَلَاةٍ مَكْتُوبَةٍ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ ‏ ‏وَقَالَ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏بِهَذَا ‏ ‏وَعَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏وَرَّادٍ ‏ ‏بِهَذَا ‏ ‏وَقَالَ ‏ ‏الْحَسَنُ ‏ ‏الْجَدُّ غِنًى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2907f563-e108-5d89-a56b-ccc661855c6f', '5cb5e738-220a-4267-901a-841c834b5d56', '800', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو رَجَاءٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدَبٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى صَلَاةً أَقْبَلَ عَلَيْنَا بِوَجْهِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c58e001b-475c-56c9-9098-78549cf71b5d', '5cb5e738-220a-4267-901a-841c834b5d56', '801', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلَّى لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الصُّبْحِ ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏عَلَى ‏ ‏إِثْرِ سَمَاءٍ ‏ ‏كَانَتْ مِنْ اللَّيْلَةِ فَلَمَّا انْصَرَفَ أَقْبَلَ عَلَى النَّاسِ فَقَالَ هَلْ تَدْرُونَ مَاذَا قَالَ رَبُّكُمْ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏أَصْبَحَ مِنْ عِبَادِي مُؤْمِنٌ بِي وَكَافِرٌ فَأَمَّا مَنْ قَالَ مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ فَذَلِكَ مُؤْمِنٌ بِي وَكَافِرٌ بِالْكَوْكَبِ وَأَمَّا مَنْ قَالَ ‏ ‏بِنَوْءِ ‏ ‏كَذَا وَكَذَا فَذَلِكَ كَافِرٌ بِي وَمُؤْمِنٌ بِالْكَوْكَبِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cdd8edfc-0d9f-5a48-8268-4e6f54156820', '5cb5e738-220a-4267-901a-841c834b5d56', '802', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُنِيرٍ ‏ ‏سَمِعَ ‏ ‏يَزِيدَ بْنَ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَخَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ ذَاتَ لَيْلَةٍ إِلَى ‏ ‏شَطْرِ ‏ ‏اللَّيْلِ ثُمَّ خَرَجَ عَلَيْنَا فَلَمَّا صَلَّى أَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ ‏ ‏إِنَّ النَّاسَ قَدْ صَلَّوْا وَرَقَدُوا وَإِنَّكُمْ لَنْ تَزَالُوا فِي صَلَاةٍ مَا انْتَظَرْتُمْ الصَّلَاةَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f890f3e4-a586-5afc-a9e7-419f36844fc9', '5cb5e738-220a-4267-901a-841c834b5d56', '803', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏هِنْدٍ بِنْتِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا سَلَّمَ يَمْكُثُ فِي مَكَانِهِ يَسِيرًا ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏فَنُرَى وَاللَّهُ أَعْلَمُ لِكَيْ يَنْفُذَ مَنْ يَنْصَرِفُ مِنْ النِّسَاءِ ‏ ‏وَقَالَ ‏ ‏ابْنُ أَبِي مَرْيَمَ ‏ ‏أَخْبَرَنَا ‏ ‏نَافِعُ بْنُ يَزِيدَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَعْفَرُ بْنُ رَبِيعَةَ ‏ ‏أَنَّ ‏ ‏ابْنَ شِهَابٍ ‏ ‏كَتَبَ إِلَيْهِ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏هِنْدُ بِنْتُ الْحَارِثِ الْفِرَاسِيَّةُ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَتْ مِنْ صَوَاحِبَاتِهَا ‏ ‏قَالَتْ ‏ ‏كَانَ يُسَلِّمُ فَيَنْصَرِفُ النِّسَاءُ فَيَدْخُلْنَ بُيُوتَهُنَّ مِنْ قَبْلِ أَنْ يَنْصَرِفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَخْبَرَتْنِي ‏ ‏هِنْدُ الْفِرَاسِيَّةُ ‏ ‏وَقَالَ ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَتْنِي ‏ ‏هِنْدُ الْفِرَاسِيَّةُ ‏ ‏وَقَالَ ‏ ‏الزُّبَيْدِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏أَنَّ ‏ ‏هِنْدَ بِنْتَ الْحَارِثِ الْقُرَشِيَّةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏وَكَانَتْ تَحْتَ ‏ ‏مَعْبَدِ بْنِ الْمِقْدَادِ ‏ ‏وَهُوَ حَلِيفُ ‏ ‏بَنِي زُهْرَةَ ‏ ‏وَكَانَتْ تَدْخُلُ عَلَى أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَتْنِي ‏ ‏هِنْدُ الْقُرَشِيَّةُ ‏ ‏وَقَالَ ‏ ‏ابْنُ أَبِي عَتِيقٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏هِنْدٍ الْفِرَاسِيَّةِ ‏ ‏وَقَالَ ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏امْرَأَةٍ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏حَدَّثَتْهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ