insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f4103317-ff48-5749-a1df-acb3cdfb7466', '5cb5e738-220a-4267-901a-841c834b5d56', '804', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدِ بْنِ مَيْمُونٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ سَعِيدٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ وَرَاءَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَدِينَةِ ‏ ‏الْعَصْرَ فَسَلَّمَ ثُمَّ قَامَ مُسْرِعًا ‏ ‏فَتَخَطَّى رِقَابَ ‏ ‏النَّاسِ إِلَى بَعْضِ حُجَرِ نِسَائِهِ فَفَزِعَ النَّاسُ مِنْ سُرْعَتِهِ فَخَرَجَ عَلَيْهِمْ فَرَأَى أَنَّهُمْ عَجِبُوا مِنْ سُرْعَتِهِ فَقَالَ ‏ ‏ذَكَرْتُ شَيْئًا مِنْ ‏ ‏تِبْرٍ ‏ ‏عِنْدَنَا فَكَرِهْتُ أَنْ يَحْبِسَنِي فَأَمَرْتُ بِقِسْمَتِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d5c339a9-6111-5bc8-945a-f3a53731ceed', '5cb5e738-220a-4267-901a-841c834b5d56', '805', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَا يَجْعَلْ أَحَدُكُمْ لِلشَّيْطَانِ شَيْئًا مِنْ صَلَاتِهِ يَرَى أَنَّ حَقًّا عَلَيْهِ أَنْ لَا يَنْصَرِفَ إِلَّا عَنْ يَمِينِهِ ‏ ‏لَقَدْ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَثِيرًا يَنْصَرِفُ عَنْ يَسَارِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7bdcbe1a-e1b5-5d18-b93f-222768f9fa38', '5cb5e738-220a-4267-901a-841c834b5d56', '806', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي ‏ ‏غَزْوَةِ ‏ ‏خَيْبَرَ ‏ ‏مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ ‏ ‏يَعْنِي الثُّومَ فَلَا يَقْرَبَنَّ مَسْجِدَنَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e7e6f0b4-e4ea-5c97-a7c6-ff19afb32f28', '5cb5e738-220a-4267-901a-841c834b5d56', '807', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ يُرِيدُ الثُّومَ فَلَا ‏ ‏يَغْشَانَا ‏ ‏فِي مَسَاجِدِنَا ‏ ‏قُلْتُ مَا ‏ ‏يَعْنِي بِهِ قَالَ مَا أُرَاهُ ‏ ‏يَعْنِي إِلَّا نِيئَهُ ‏ ‏وَقَالَ ‏ ‏مَخْلَدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏إِلَّا نَتْنَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d6a8537f-14f2-5329-9b08-d7bf1c58a758', '5cb5e738-220a-4267-901a-841c834b5d56', '808', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عُفَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏زَعَمَ ‏ ‏عَطَاءٌ ‏ ‏أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏زَعَمَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَكَلَ ثُومًا أَوْ بَصَلًا فَلْيَعْتَزِلْنَا أَوْ قَالَ فَلْيَعْتَزِلْ مَسْجِدَنَا وَلْيَقْعُدْ فِي بَيْتِهِ وَأَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِقِدْرٍ فِيهِ خَضِرَاتٌ مِنْ بُقُولٍ فَوَجَدَ لَهَا رِيحًا فَسَأَلَ فَأُخْبِرَ بِمَا فِيهَا مِنْ الْبُقُولِ فَقَالَ قَرِّبُوهَا إِلَى بَعْضِ أَصْحَابِهِ كَانَ مَعَهُ فَلَمَّا رَآهُ كَرِهَ أَكْلَهَا قَالَ كُلْ فَإِنِّي ‏ ‏أُنَاجِي ‏ ‏مَنْ لَا ‏ ‏تُنَاجِي ‏ ‏وَقَالَ ‏ ‏أَحْمَدُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏ابْنِ وَهْبٍ ‏ ‏أُتِيَ ‏ ‏بِبَدْرٍ ‏ ‏وَقَالَ ‏ ‏ابْنُ وَهْبٍ ‏ ‏يَعْنِي طَبَقًا فِيهِ خَضِرَاتٌ ‏ ‏وَلَمْ يَذْكُرِ ‏ ‏اللَّيْثُ ‏ ‏وَأَبُو صَفْوَانَ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏قِصَّةَ الْقِدْرِ ‏ ‏فَلَا أَدْرِي هُوَ مِنْ قَوْلِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَوْ فِي الْحَدِيثِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('44b98212-9bdf-5cee-b106-d017c3b50b97', '5cb5e738-220a-4267-901a-841c834b5d56', '809', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏قَالَ سَأَلَ رَجُلٌ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏مَا سَمِعْتَ نَبِيَّ اللَّه ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي الثُّومِ فَقَالَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ فَلَا يَقْرَبْنَا أَوْ لَا يُصَلِّيَنَّ مَعَنَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('02ea6269-fc44-597b-9dff-211f5f3541a6', '5cb5e738-220a-4267-901a-841c834b5d56', '810', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏غُنْدَرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ الشَّيْبَانِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْ مَرَّ ‏ ‏مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى قَبْرٍ ‏ ‏مَنْبُوذٍ ‏ ‏فَأَمَّهُمْ وَصَفُّوا عَلَيْهِ فَقُلْتُ يَا ‏ ‏أَبَا عَمْرٍو ‏ ‏مَنْ حَدَّثَكَ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7930e06d-a83d-5f2a-b5ad-89a736919076', '5cb5e738-220a-4267-901a-841c834b5d56', '811', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏صَفْوَانُ بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْغُسْلُ يَوْمَ الْجُمُعَةِ وَاجِبٌ عَلَى كُلِّ ‏ ‏مُحْتَلِمٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('336bd662-af26-5019-8797-a2d43a8600d0', '5cb5e738-220a-4267-901a-841c834b5d56', '812', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏كُرَيْبٌ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏بِتُّ عِنْدَ خَالَتِي ‏ ‏مَيْمُونَةَ ‏ ‏لَيْلَةً فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا كَانَ فِي بَعْضِ اللَّيْلِ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَوَضَّأَ مِنْ ‏ ‏شَنٍّ ‏ ‏مُعَلَّقٍ وُضُوءًا خَفِيفًا ‏ ‏يُخَفِّفُهُ ‏ ‏عَمْرٌو ‏ ‏وَيُقَلِّلُهُ جِدًّا ‏ ‏ثُمَّ قَامَ ‏ ‏يُصَلِّي فَقُمْتُ فَتَوَضَّأْتُ نَحْوًا مِمَّا تَوَضَّأَ ثُمَّ جِئْتُ فَقُمْتُ عَنْ يَسَارِهِ فَحَوَّلَنِي فَجَعَلَنِي عَنْ يَمِينِهِ ثُمَّ صَلَّى مَا شَاءَ اللَّهُ ثُمَّ اضْطَجَعَ فَنَامَ حَتَّى نَفَخَ فَأَتَاهُ الْمُنَادِي يَأْذَنُهُ بِالصَّلَاةِ فَقَامَ مَعَهُ إِلَى الصَّلَاةِ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏ ‏قُلْنَا ‏ ‏لِعَمْرٍو ‏ ‏إِنَّ نَاسًا يَقُولُونَ إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَنَامُ عَيْنُهُ وَلَا يَنَامُ قَلْبُهُ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏سَمِعْتُ ‏ ‏عُبَيْدَ بْنَ عُمَيْرٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ رُؤْيَا الْأَنْبِيَاءِ وَحْيٌ ثُمَّ قَرَأَ ‏ { ‏إِنِّي أَرَى فِي الْمَنَامِ أَنِّي أَذْبَحُكَ ‏}', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6b221378-9b83-5b75-bd36-e67e6eaa327e', '5cb5e738-220a-4267-901a-841c834b5d56', '813', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ جَدَّتَهُ ‏ ‏مُلَيْكَةَ ‏ ‏دَعَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِطَعَامٍ صَنَعَتْهُ فَأَكَلَ مِنْهُ فَقَالَ ‏ ‏قُومُوا فَلِأُصَلِّيَ بِكُمْ فَقُمْتُ إِلَى حَصِيرٍ لَنَا قَدْ اسْوَدَّ مِنْ طُولِ مَا لَبِثَ فَنَضَحْتُهُ بِمَاءٍ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْيَتِيمُ مَعِي وَالْعَجُوزُ مِنْ وَرَائِنَا فَصَلَّى بِنَا رَكْعَتَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0462d409-a6e2-5ac6-bc53-78feed108384', '5cb5e738-220a-4267-901a-841c834b5d56', '814', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّهُ قَالَ ‏ ‏أَقْبَلْتُ رَاكِبًا عَلَى حِمَارٍ ‏ ‏أَتَانٍ ‏ ‏وَأَنَا يَوْمَئِذٍ قَدْ ‏ ‏نَاهَزْتُ ‏ ‏الِاحْتِلَامَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِالنَّاسِ ‏ ‏بِمِنًى ‏ ‏إِلَى غَيْرِ جِدَارٍ فَمَرَرْتُ بَيْنَ يَدَيْ بَعْضِ الصَّفِّ فَنَزَلْتُ وَأَرْسَلْتُ ‏ ‏الْأَتَانَ ‏ ‏تَرْتَعُ ‏ ‏وَدَخَلْتُ فِي الصَّفِّ فَلَمْ يُنْكِرْ ذَلِكَ عَلَيَّ أَحَدٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e220484e-006e-5136-92cb-aed0bc7f4aad', '5cb5e738-220a-4267-901a-841c834b5d56', '815', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَعْتَمَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏عَيَّاشٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏أَعْتَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْعِشَاءِ حَتَّى نَادَاهُ ‏ ‏عُمَرُ ‏ ‏قَدْ نَامَ النِّسَاءُ وَالصِّبْيَانُ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّهُ لَيْسَ أَحَدٌ مِنْ أَهْلِ الْأَرْضِ ‏ ‏يُصَلِّي هَذِهِ الصَّلَاةَ غَيْرُكُمْ وَلَمْ يَكُنْ أَحَدٌ يَوْمَئِذٍ ‏ ‏يُصَلِّي غَيْرَ ‏ ‏أَهْلِ ‏ ‏الْمَدِينَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e1a62462-8065-5438-a698-2101dc36017d', '5cb5e738-220a-4267-901a-841c834b5d56', '816', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَابِسٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ لَهُ رَجُلٌ شَهِدْتَ الْخُرُوجَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ وَلَوْلَا مَكَانِي مِنْهُ مَا شَهِدْتُهُ ‏ ‏يَعْنِي مِنْ صِغَرِهِ ‏ ‏أَتَى الْعَلَمَ الَّذِي عِنْدَ دَارِ ‏ ‏كَثِيرِ بْنِ الصَّلْتِ ‏ ‏ثُمَّ خَطَبَ ثُمَّ أَتَى النِّسَاءَ فَوَعَظَهُنَّ وَذَكَّرَهُنَّ وَأَمَرَهُنَّ أَنْ يَتَصَدَّقْنَ فَجَعَلَتْ الْمَرْأَةُ تُهْوِي بِيَدِهَا إِلَى حَلْقِهَا تُلْقِي فِي ثَوْبِ ‏ ‏بِلَالٍ ‏ ‏ثُمَّ أَتَى هُوَ ‏ ‏وَبِلَالٌ ‏ ‏الْبَيْتَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('527ca58c-f936-513b-9104-c4ba9bac2b5e', '5cb5e738-220a-4267-901a-841c834b5d56', '817', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏أَعْتَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْعَتَمَةِ ‏ ‏حَتَّى نَادَاهُ ‏ ‏عُمَرُ ‏ ‏نَامَ النِّسَاءُ وَالصِّبْيَانُ فَخَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا يَنْتَظِرُهَا أَحَدٌ غَيْرُكُمْ مِنْ أَهْلِ الْأَرْضِ وَلَا يُصَلَّى يَوْمَئِذٍ إِلَّا ‏ ‏بِالْمَدِينَةِ ‏ ‏وَكَانُوا يُصَلُّونَ ‏ ‏الْعَتَمَةَ ‏ ‏فِيمَا بَيْنَ أَنْ يَغِيبَ ‏ ‏الشَّفَقُ ‏ ‏إِلَى ثُلُثِ اللَّيْلِ الْأَوَّلِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('30988491-84f6-508f-a001-839494e5786f', '5cb5e738-220a-4267-901a-841c834b5d56', '818', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَأْذَنَكُمْ نِسَاؤُكُمْ بِاللَّيْلِ إِلَى الْمَسْجِدِ فَأْذَنُوا لَهُنَّ ‏ ‏تَابَعَهُ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cff96acb-7999-5684-b0f6-2b4eb9ef1c49', '5cb5e738-220a-4267-901a-841c834b5d56', '819', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏هِنْدُ بِنْتُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهَا ‏ ‏أَنَّ النِّسَاءَ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُنَّ إِذَا سَلَّمْنَ مِنْ الْمَكْتُوبَةِ قُمْنَ وَثَبَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَنْ صَلَّى مِنْ الرِّجَالِ مَا شَاءَ اللَّهُ فَإِذَا قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ الرِّجَالُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bd2c023d-4adb-58c9-9a88-ad239777e979', '5cb5e738-220a-4267-901a-841c834b5d56', '820', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُصَلِّي الصُّبْحَ فَيَنْصَرِفُ النِّسَاءُ ‏ ‏مُتَلَفِّعَاتٍ ‏ ‏بِمُرُوطِهِنَّ ‏ ‏مَا يُعْرَفْنَ مِنْ ‏ ‏الْغَلَسِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1842b8d8-1b05-5416-b0d8-a87b5736b52a', '5cb5e738-220a-4267-901a-841c834b5d56', '821', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مِسْكِينٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بِشْرُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَقُومُ إِلَى الصَّلَاةِ وَأَنَا أُرِيدُ أَنْ أُطَوِّلَ فِيهَا فَأَسْمَعُ بُكَاءَ الصَّبِيِّ ‏ ‏فَأَتَجَوَّزُ ‏ ‏فِي صَلَاتِي كَرَاهِيَةَ أَنْ أَشُقَّ عَلَى أُمِّهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0bfb474d-d37e-56d5-9793-134a44aafa4b', '5cb5e738-220a-4267-901a-841c834b5d56', '822', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏لَوْ أَدْرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَحْدَثَ النِّسَاءُ لَمَنَعَهُنَّ كَمَا مُنِعَتْ نِسَاءُ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏قُلْتُ ‏ ‏لِعَمْرَةَ ‏ ‏أَوَمُنِعْنَ قَالَتْ نَعَمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b3837ade-1053-572c-9592-1211661b4586', '5cb5e738-220a-4267-901a-841c834b5d56', '823', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ قَزَعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏هِنْدٍ بِنْتِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَلَّمَ قَامَ النِّسَاءُ حِينَ يَقْضِي تَسْلِيمَهُ وَيَمْكُثُ هُوَ فِي مَقَامِهِ يَسِيرًا قَبْلَ أَنْ يَقُومَ ‏ ‏قَالَ ‏ ‏نَرَى وَاللَّهُ أَعْلَمُ أَنَّ ذَلِكَ كَانَ لِكَيْ يَنْصَرِفَ النِّسَاءُ قَبْلَ أَنْ يُدْرِكَهُنَّ أَحَدٌ مِنْ الرِّجَالِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('79373e6a-daee-5236-a081-9772e44a8e0a', '5cb5e738-220a-4267-901a-841c834b5d56', '824', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِ ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏فَقُمْتُ وَيَتِيمٌ خَلْفَهُ ‏ ‏وَأُمُّ سُلَيْمٍ ‏ ‏خَلْفَنَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('617ce5ff-3556-51ea-ba90-964bc2b16ec0', '5cb5e738-220a-4267-901a-841c834b5d56', '825', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الصُّبْحَ ‏ ‏بِغَلَسٍ ‏ ‏فَيَنْصَرِفْنَ نِسَاءُ الْمُؤْمِنِينَ لَا يُعْرَفْنَ مِنْ ‏ ‏الْغَلَسِ ‏ ‏أَوْ لَا يَعْرِفُ بَعْضُهُنَّ بَعْضًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('db5d3817-85ab-5131-b741-97b9a52baf8e', '5cb5e738-220a-4267-901a-841c834b5d56', '826', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَأْذَنَتْ امْرَأَةُ أَحَدِكُمْ فَلَا يَمْنَعْهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7ac67eb7-ece4-5b09-a051-92f7e9c54d1f', '5cb5e738-220a-4267-901a-841c834b5d56', '827', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الزِّنَادِ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ هُرْمُزَ الْأَعْرَجَ ‏ ‏مَوْلَى ‏ ‏رَبِيعَةَ بْنِ الْحَارِثِ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏نَحْنُ الْآخِرُونَ السَّابِقُونَ يَوْمَ الْقِيَامَةِ بَيْدَ أَنَّهُمْ أُوتُوا الْكِتَابَ مِنْ قَبْلِنَا ثُمَّ هَذَا يَوْمُهُمْ الَّذِي فُرِضَ عَلَيْهِمْ فَاخْتَلَفُوا فِيهِ فَهَدَانَا اللَّهُ فَالنَّاسُ لَنَا فِيهِ تَبَعٌ ‏ ‏الْيَهُودُ ‏ ‏غَدًا ‏ ‏وَالنَّصَارَى ‏ ‏بَعْدَ غَدٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7e721682-1438-57c4-973e-d77a5d8f693c', '5cb5e738-220a-4267-901a-841c834b5d56', '828', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَاءَ أَحَدُكُمْ الْجُمُعَةَ فَلْيَغْتَسِلْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6f043666-b68b-5d9e-b98e-dd500ba47552', '5cb5e738-220a-4267-901a-841c834b5d56', '829', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَسْمَاءَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏جُوَيْرِيَةُ بْنُ أَسْمَاءَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏بَيْنَمَا هُوَ قَائِمٌ فِي الْخُطْبَةِ يَوْمَ الْجُمُعَةِ إِذْ دَخَلَ رَجُلٌ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏الْأَوَّلِينَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَادَاهُ ‏ ‏عُمَرُ ‏ ‏أَيَّةُ سَاعَةٍ هَذِهِ قَالَ إِنِّي شُغِلْتُ فَلَمْ ‏ ‏أَنْقَلِبْ ‏ ‏إِلَى أَهْلِي حَتَّى سَمِعْتُ التَّأْذِينَ فَلَمْ أَزِدْ أَنْ تَوَضَّأْتُ فَقَالَ وَالْوُضُوءُ أَيْضًا وَقَدْ عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْمُرُ بِالْغُسْلِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('77e7ac59-973e-5912-bf2c-51c9b6ba8241', '5cb5e738-220a-4267-901a-841c834b5d56', '830', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏غُسْلُ يَوْمِ الْجُمُعَةِ وَاجِبٌ عَلَى كُلِّ مُحْتَلِمٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('54a172c7-d8cb-5caa-a9c0-c54317b59605', '5cb5e738-220a-4267-901a-841c834b5d56', '831', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرَمِيُّ بْنُ عُمَارَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَكرِ بْنِ الْمُنكَدِرِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ سُلَيْمٍ الْأَنْصَارِيُّ ‏ ‏قَالَ أَشْهَدُ عَلَى ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏أَشْهَدُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْغُسْلُ يَوْمَ الْجُمُعَةِ وَاجِبٌ عَلَى كُلِّ مُحْتَلِمٍ وَأَنْ ‏ ‏يَسْتَنَّ ‏ ‏وَأَنْ يَمَسَّ طِيبًا إِنْ وَجَدَ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏أَمَّا الْغُسْلُ فَأَشْهَدُ أَنَّهُ وَاجِبٌ وَأَمَّا ‏ ‏الِاسْتِنَانُ ‏ ‏وَالطِّيبُ فَاللَّهُ أَعْلَمُ أَوَاجِبٌ هُوَ أَمْ لَا وَلَكِنْ هَكَذَا فِي الْحَدِيثِ ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏هُوَ أَخُو ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏وَلَمْ يُسَمَّ ‏ ‏أَبُو بَكْرٍ ‏ ‏هَذَا ‏ ‏رَوَاهُ عَنْهُ ‏ ‏بُكَيْرُ بْنُ الْأَشَجِّ ‏ ‏وَسَعِيدُ بْنُ أَبِي هِلَالٍ ‏ ‏وَعِدَّةٌ وَكَانَ ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏يُكْنَى ‏ ‏بِأَبِي بَكْرٍ ‏ ‏وَأَبِي عَبْدِ اللَّهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b02c59d6-a498-55ce-9d63-94c3aaf04610', '5cb5e738-220a-4267-901a-841c834b5d56', '832', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اغْتَسَلَ يَوْمَ الْجُمُعَةِ غُسْلَ الْجَنَابَةِ ثُمَّ رَاحَ فَكَأَنَّمَا ‏ ‏قَرَّبَ ‏ ‏بَدَنَةً ‏ ‏وَمَنْ رَاحَ فِي السَّاعَةِ الثَّانِيَةِ فَكَأَنَّمَا ‏ ‏قَرَّبَ ‏ ‏بَقَرَةً وَمَنْ رَاحَ فِي السَّاعَةِ الثَّالِثَةِ فَكَأَنَّمَا ‏ ‏قَرَّبَ ‏ ‏كَبْشًا أَقْرَنَ وَمَنْ رَاحَ فِي السَّاعَةِ الرَّابِعَةِ فَكَأَنَّمَا ‏ ‏قَرَّبَ ‏ ‏دَجَاجَةً وَمَنْ رَاحَ فِي السَّاعَةِ الْخَامِسَةِ فَكَأَنَّمَا ‏ ‏قَرَّبَ ‏ ‏بَيْضَةً فَإِذَا خَرَجَ الْإِمَامُ حَضَرَتْ الْمَلَائِكَةُ يَسْتَمِعُونَ الذِّكْرَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eeb6abc2-f274-552f-ad1f-83b68634371a', '5cb5e738-220a-4267-901a-841c834b5d56', '833', '‏ ‏بَاب ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى هُوَ ابْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بَيْنَمَا هُوَ يَخْطُبُ يَوْمَ الْجُمُعَةِ إِذْ دَخَلَ رَجُلٌ فَقَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لِمَ ‏ ‏تَحْتَبِسُونَ ‏ ‏عَنْ الصَّلَاةِ فَقَالَ الرَّجُلُ مَا هُوَ إِلَّا أَنْ سَمِعْتُ النِّدَاءَ تَوَضَّأْتُ فَقَالَ أَلَمْ تَسْمَعُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا رَاحَ أَحَدُكُمْ إِلَى الْجُمُعَةِ فَلْيَغْتَسِلْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f7b09d28-8710-56ee-b7d7-1ffbe34b2b37', '5cb5e738-220a-4267-901a-841c834b5d56', '834', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ وَدِيعَةَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ الْفَارِسِيِّ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَغْتَسِلُ رَجُلٌ يَوْمَ الْجُمُعَةِ وَيَتَطَهَّرُ مَا اسْتَطَاعَ مِنْ طُهْرٍ وَيَدَّهِنُ مِنْ دُهْنِهِ أَوْ يَمَسُّ مِنْ طِيبِ بَيْتِهِ ثُمَّ يَخْرُجُ فَلَا يُفَرِّقُ بَيْنَ اثْنَيْنِ ثُمَّ ‏ ‏يُصَلِّي مَا كُتِبَ لَهُ ثُمَّ يُنْصِتُ إِذَا تَكَلَّمَ الْإِمَامُ إِلَّا غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ الْأُخْرَى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d528f13d-274f-5e88-9dc4-db251a994b1e', '5cb5e738-220a-4267-901a-841c834b5d56', '835', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏طَاوُسٌ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏ذَكَرُوا ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اغْتَسِلُوا يَوْمَ الْجُمُعَةِ وَاغْسِلُوا رُءُوسَكُمْ وَإِنْ لَمْ تَكُونُوا جُنُبًا ‏ ‏وَأَصِيبُوا ‏ ‏مِنْ الطِّيبِ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَمَّا الْغُسْلُ فَنَعَمْ وَأَمَّا الطِّيبُ فَلَا أَدْرِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2ca93f82-88a1-5bc9-be58-250da864b886', '5cb5e738-220a-4267-901a-841c834b5d56', '836', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏أَنَّ ‏ ‏ابْنَ جُرَيْجٍ ‏ ‏أَخْبَرَهُمْ قَالَ أَخْبَرَنِي ‏ ‏إِبْرَاهِيمُ بْنُ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّهُ ذَكَرَ قَوْلَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْغُسْلِ يَوْمَ الْجُمُعَةِ فَقُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏أَيَمَسُّ طِيبًا أَوْ دُهْنًا إِنْ كَانَ عِنْدَ أَهْلِهِ فَقَالَ لَا أَعْلَمُهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('19b79b92-ee3d-578f-8518-86cef961c5bb', '5cb5e738-220a-4267-901a-841c834b5d56', '837', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَأَى ‏ ‏حُلَّةً ‏ ‏سِيَرَاءَ ‏ ‏عِنْدَ بَابِ الْمَسْجِدِ فَقَالَ يَا رَسُولَ اللَّهِ لَوْ اشْتَرَيْتَ هَذِهِ فَلَبِسْتَهَا يَوْمَ الْجُمُعَةِ وَلِلْوَفْدِ إِذَا قَدِمُوا عَلَيْكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا يَلْبَسُ هَذِهِ مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ فِي الْآخِرَةِ ثُمَّ جَاءَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهَا ‏ ‏حُلَلٌ ‏ ‏فَأَعْطَى ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مِنْهَا ‏ ‏حُلَّةً ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ كَسَوْتَنِيهَا وَقَدْ قُلْتَ فِي ‏ ‏حُلَّةِ ‏ ‏عُطَارِدٍ مَا قُلْتَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَمْ أَكْسُكَهَا لِتَلْبَسَهَا فَكَسَاهَا ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَخًا ‏ ‏لَهُ ‏ ‏بِمَكَّةَ ‏ ‏مُشْرِكًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('edd247a9-3cf4-5403-a0d9-39c1b9f2abfe', '5cb5e738-220a-4267-901a-841c834b5d56', '838', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي أَوْ عَلَى النَّاسِ لَأَمَرْتُهُمْ بِالسِّوَاكِ مَعَ كُلِّ صَلَاةٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('50dbed34-0b16-5d00-b46e-03482adde965', '5cb5e738-220a-4267-901a-841c834b5d56', '839', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ الْحَبْحَابِ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسٌ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْثَرْتُ عَلَيْكُمْ فِي السِّوَاكِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('604cdab9-161c-5a4e-8698-b1179c062589', '5cb5e738-220a-4267-901a-841c834b5d56', '840', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَحُصَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ مِنْ اللَّيْلِ ‏ ‏يَشُوصُ ‏ ‏فَاهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('07df32fd-3f8e-5064-a910-34a47137d19c', '5cb5e738-220a-4267-901a-841c834b5d56', '841', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏قَالَ قَالَ ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏دَخَلَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرٍ ‏ ‏وَمَعَهُ سِوَاكٌ ‏ ‏يَسْتَنُّ ‏ ‏بِهِ فَنَظَرَ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ لَهُ أَعْطِنِي هَذَا السِّوَاكَ يَا ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏فَأَعْطَانِيهِ ‏ ‏فَقَصَمْتُهُ ‏ ‏ثُمَّ مَضَغْتُهُ ‏ ‏فَأَعْطَيْتُهُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَنَّ ‏ ‏بِهِ وَهُوَ مُسْتَسْنِدٌ إِلَى صَدْرِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cdddfb6e-e0f2-5b5e-8ca9-d517ba929cb2', '5cb5e738-220a-4267-901a-841c834b5d56', '842', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ هُوَ ابْنُ هُرْمُزَ الْأَعْرَجُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الْجُمُعَةِ فِي صَلَاةِ الْفَجْرِ ‏ ‏الم تَنْزِيلُ السَّجْدَةَ ‏ ‏وَهَلْ أَتَى عَلَى الْإِنْسَانِ حِينٌ مِنْ الدَّهْرِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('053cc371-891a-5834-929b-647e820fe07a', '5cb5e738-220a-4267-901a-841c834b5d56', '843', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ الْعَقَدِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ طَهْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي جَمْرَةَ الضُّبَعِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ أَوَّلَ جُمُعَةٍ جُمِّعَتْ بَعْدَ جُمُعَةٍ فِي ‏ ‏مَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَسْجِدِ ‏ ‏عَبْدِ الْقَيْسِ ‏ ‏بِجُوَاثَى ‏ ‏مِنْ ‏ ‏الْبَحْرَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d41a8bb6-e803-5cce-b929-84ad41d2d4cb', '5cb5e738-220a-4267-901a-841c834b5d56', '844', '‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ مُحَمَّدٍ الْمَرْوَزِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كُلُّكُمْ رَاعٍ ‏ ‏وَزَادَ ‏ ‏اللَّيْثُ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏كَتَبَ ‏ ‏رُزَيْقُ بْنُ حُكَيْمٍ ‏ ‏إِلَى ‏ ‏ابْنِ شِهَابٍ ‏ ‏وَأَنَا مَعَهُ يَوْمَئِذٍ ‏ ‏بِوَادِي الْقُرَى ‏ ‏هَلْ تَرَى أَنْ أُجَمِّعَ ‏ ‏وَرُزَيْقٌ ‏ ‏عَامِلٌ عَلَى أَرْضٍ يَعْمَلُهَا وَفِيهَا جَمَاعَةٌ مِنْ ‏ ‏السُّودَانِ ‏ ‏وَغَيْرِهِمْ ‏ ‏وَرُزَيْقٌ ‏ ‏يَوْمَئِذٍ عَلَى ‏ ‏أَيْلَةَ ‏ ‏فَكَتَبَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَأَنَا أَسْمَعُ يَأْمُرُهُ أَنْ يُجَمِّعَ يُخْبِرُهُ ‏ ‏أَنَّ ‏ ‏سَالِمًا ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ الْإِمَامُ رَاعٍ وَمَسْئُولٌ عَنْ رَعِيَّتِهِ وَالرَّجُلُ رَاعٍ فِي أَهْلِهِ وَهُوَ مَسْئُولٌ عَنْ رَعِيَّتِهِ وَالْمَرْأَةُ رَاعِيَةٌ فِي بَيْتِ زَوْجِهَا وَمَسْئُولَةٌ عَنْ رَعِيَّتِهَا وَالْخَادِمُ رَاعٍ فِي مَالِ سَيِّدِهِ وَمَسْئُولٌ عَنْ رَعِيَّتِهِ قَالَ وَحَسِبْتُ أَنْ قَدْ قَالَ وَالرَّجُلُ رَاعٍ فِي مَالِ أَبِيهِ وَمَسْئُولٌ عَنْ رَعِيَّتِهِ وَكُلُّكُمْ رَاعٍ وَمَسْئُولٌ عَنْ رَعِيَّتِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ea67affd-6daa-5067-9948-09cc34ff429d', '5cb5e738-220a-4267-901a-841c834b5d56', '845', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ جَاءَ مِنْكُمْ الْجُمُعَةَ فَلْيَغْتَسِلْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('49901fc4-c429-5448-ac3b-0c00870cc3fc', '5cb5e738-220a-4267-901a-841c834b5d56', '846', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏غُسْلُ يَوْمِ الْجُمُعَةِ وَاجِبٌ عَلَى كُلِّ مُحْتَلِمٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e4653931-089f-5d11-a2cb-32a4a126b8e9', '5cb5e738-220a-4267-901a-841c834b5d56', '847', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْنُ الْآخِرُونَ السَّابِقُونَ يَوْمَ الْقِيَامَةِ أُوتُوا الْكِتَابَ مِنْ قَبْلِنَا وَأُوتِينَاهُ مِنْ بَعْدِهِمْ فَهَذَا الْيَوْمُ الَّذِي اخْتَلَفُوا فِيهِ فَهَدَانَا اللَّهُ فَغَدًا ‏ ‏لِلْيَهُودِ ‏ ‏وَبَعْدَ غَدٍ ‏ ‏لِلنَّصَارَى ‏ ‏فَسَكَتَ ثُمَّ قَالَ ‏ ‏حَقٌّ عَلَى كُلِّ مُسْلِمٍ أَنْ يَغْتَسِلَ فِي كُلِّ سَبْعَةِ أَيَّامٍ يَوْمًا يَغْسِلُ فِيهِ رَأْسَهُ وَجَسَدَهُ ‏ ‏رَوَاهُ ‏ ‏أَبَانُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلَّهِ تَعَالَى عَلَى كُلِّ مُسْلِمٍ حَقٌّ أَنْ يَغْتَسِلَ فِي كُلِّ سَبْعَةِ أَيَّامٍ يَوْمًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3054676b-7f89-555b-a87a-991a864cd09c', '5cb5e738-220a-4267-901a-841c834b5d56', '848', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَبَابَةُ ‏ ‏حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ائْذَنُوا لِلنِّسَاءِ بِاللَّيْلِ إِلَى الْمَسَاجِدِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('537ed9cf-d0b6-5d74-9255-aed7acfe4691', '5cb5e738-220a-4267-901a-841c834b5d56', '849', '‏ ‏حَدَّثَنَا ‏ ‏يُوسُفُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏امْرَأَةٌ ‏ ‏لِعُمَرَ ‏ ‏تَشْهَدُ صَلَاةَ الصُّبْحِ وَالْعِشَاءِ فِي الْجَمَاعَةِ فِي الْمَسْجِدِ فَقِيلَ لَهَا لِمَ تَخْرُجِينَ وَقَدْ تَعْلَمِينَ أَنَّ ‏ ‏عُمَرَ ‏ ‏يَكْرَهُ ذَلِكَ وَيَغَارُ قَالَتْ وَمَا يَمْنَعُهُ أَنْ يَنْهَانِي قَالَ يَمْنَعُهُ قَوْلُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمْنَعُوا إِمَاءَ اللَّهِ مَسَاجِدَ اللَّهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('74741587-e7af-52c2-9541-795a0f48c490', '5cb5e738-220a-4267-901a-841c834b5d56', '850', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏صَاحِبُ ‏ ‏الزِّيَادِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏ابْنُ عَمِّ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لِمُؤَذِّنِهِ فِي يَوْمٍ مَطِيرٍ إِذَا قُلْتَ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ فَلَا تَقُلْ حَيَّ عَلَى الصَّلَاةِ قُلْ ‏ ‏صَلُّوا فِي بُيُوتِكُمْ فَكَأَنَّ النَّاسَ اسْتَنْكَرُوا قَالَ فَعَلَهُ مَنْ هُوَ خَيْرٌ مِنِّي إِنَّ الْجُمْعَةَ عَزْمَةٌ وَإِنِّي كَرِهْتُ أَنْ أُحْرِجَكُمْ فَتَمْشُونَ فِي الطِّينِ ‏ ‏وَالدَّحَضِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('658f454c-6c9f-5a7c-9a5c-d61d1e7c77fd', '5cb5e738-220a-4267-901a-841c834b5d56', '851', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ صَالِحٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّاسُ ‏ ‏يَنْتَابُونَ ‏ ‏يَوْمَ الْجُمُعَةِ مِنْ مَنَازِلِهِمْ ‏ ‏وَالْعَوَالِيِّ ‏ ‏فَيَأْتُونَ فِي الْغُبَارِ يُصِيبُهُمْ الْغُبَارُ وَالْعَرَقُ فَيَخْرُجُ مِنْهُمْ الْعَرَقُ فَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْسَانٌ مِنْهُمْ وَهُوَ عِنْدِي فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَنَّكُمْ تَطَهَّرْتُمْ لِيَوْمِكُمْ هَذَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dc55d104-ce0a-51a2-9990-1089029dd826', '5cb5e738-220a-4267-901a-841c834b5d56', '852', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدَانُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏عَمْرَةَ ‏ ‏عَنْ الْغُسْلِ يَوْمَ الْجُمُعَةِ ‏ ‏فَقَالَتْ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏كَانَ النَّاسُ مَهَنَةَ أَنْفُسِهِمْ وَكَانُوا إِذَا رَاحُوا إِلَى الْجُمُعَةِ رَاحُوا فِي هَيْئَتِهِمْ فَقِيلَ لَهُمْ لَوْ اغْتَسَلْتُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('beeff47d-47f4-518d-b1c9-c81c4a97722f', '5cb5e738-220a-4267-901a-841c834b5d56', '853', '‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُلَيْحُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الْجُمُعَةَ حِينَ تَمِيلُ الشَّمْسُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7650030d-709a-514a-ad82-3ada04463b4d', '5cb5e738-220a-4267-901a-841c834b5d56', '854', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدَانُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنَّا نُبَكِّرُ بِالْجُمُعَةِ ‏ ‏وَنَقِيلُ ‏ ‏بَعْدَ الْجُمُعَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ede15d38-bcaa-5b15-852f-9655d7a40372', '5cb5e738-220a-4267-901a-841c834b5d56', '855', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرَمِيُّ بْنُ عُمَارَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو خَلْدَةَ هُوَ خَالِدُ بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اشْتَدَّ الْبَرْدُ بَكَّرَ بِالصَّلَاةِ وَإِذَا اشْتَدَّ الْحَرُّ أَبْرَدَ بِالصَّلَاةِ ‏ ‏يَعْنِي الْجُمُعَةَ ‏ ‏قَالَ ‏ ‏يُونُسُ بْنُ بُكَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو خَلْدَةَ ‏ ‏فَقَالَ ‏ ‏بِالصَّلَاةِ وَلَمْ يَذْكُرْ الْجُمُعَةَ ‏ ‏وَقَالَ ‏ ‏بِشْرُ بْنُ ثَابِتٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَلْدَةَ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا أَمِيرٌ الْجُمُعَةَ ثُمَّ قَالَ ‏ ‏لِأَنَسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏كَيْفَ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الظُّهْرَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b56fea44-bd86-55bf-9a40-7c99b791dd3a', '5cb5e738-220a-4267-901a-841c834b5d56', '856', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي مَرْيَمَ الْأَنْصَارِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَايَةُ بْنُ رِفَاعَةَ ‏ ‏قَالَ أَدْرَكَنِي ‏ ‏أَبُو عَبْسٍ ‏ ‏وَأَنَا أَذْهَبُ إِلَى الْجُمُعَةِ ‏ ‏فَقَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ اغْبَرَّتْ قَدَمَاهُ فِي سَبِيلِ اللَّهِ حَرَّمَهُ اللَّهُ عَلَى النَّارِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('86751293-d130-56af-9b7e-8c5277c9bac9', '5cb5e738-220a-4267-901a-841c834b5d56', '857', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا تَأْتُوهَا ‏ ‏تَسْعَوْنَ ‏ ‏وَأْتُوهَا تَمْشُونَ عَلَيْكُمْ السَّكِينَةُ فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَأَتِمُّوا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('af1703aa-76f2-53de-a501-4206f4b20dff', '5cb5e738-220a-4267-901a-841c834b5d56', '858', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو قُتَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقُومُوا حَتَّى تَرَوْنِي وَعَلَيْكُمْ السَّكِينَةُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c5b133f7-b3c9-509d-bf33-e0671c823291', '5cb5e738-220a-4267-901a-841c834b5d56', '859', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدَانُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ وَدِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏سَلْمَانُ الْفَارِسِيُّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اغْتَسَلَ يَوْمَ الْجُمُعَةِ وَتَطَهَّرَ بِمَا اسْتَطَاعَ مِنْ طُهْرٍ ثُمَّ ‏ ‏ادَّهَنَ ‏ ‏أَوْ مَسَّ مِنْ طِيبٍ ثُمَّ رَاحَ فَلَمْ يُفَرِّقْ بَيْنَ اثْنَيْنِ فَصَلَّى مَا كُتِبَ لَهُ ثُمَّ إِذَا خَرَجَ الْإِمَامُ أَنْصَتَ غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ الْأُخْرَى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('704c3877-769d-51d6-9b79-25b04edc1d56', '5cb5e738-220a-4267-901a-841c834b5d56', '860', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ هُوَ ابْنُ سَلَّامٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَخْلَدُ بْنُ يَزِيدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏نَافِعًا ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏يَقُولُ ‏ ‏نَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُقِيمَ الرَّجُلُ أَخَاهُ مِنْ مَقْعَدِهِ وَيَجْلِسَ فِيهِ ‏ ‏قُلْتُ ‏ ‏لِنَافِعٍ ‏ ‏الْجُمُعَةَ قَالَ الْجُمُعَةَ وَغَيْرَهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('27d2a717-0ad6-5d84-9e36-4ef3886e97d8', '5cb5e738-220a-4267-901a-841c834b5d56', '861', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏النِّدَاءُ يَوْمَ الْجُمُعَةِ أَوَّلُهُ إِذَا جَلَسَ الْإِمَامُ عَلَى الْمِنْبَرِ عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏فَلَمَّا كَانَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَكَثُرَ النَّاسُ زَادَ النِّدَاءَ الثَّالِثَ عَلَى ‏ ‏الزَّوْرَاءِ ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏الزَّوْرَاءُ ‏ ‏مَوْضِعٌ بِالسُّوقِ ‏ ‏بِالْمَدِينَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4501f8fd-6b4f-5558-ac73-1a7f939a9c56', '5cb5e738-220a-4267-901a-841c834b5d56', '862', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي سَلَمَةَ الْمَاجِشُونُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏أَنَّ الَّذِي زَادَ التَّأْذِينَ الثَّالِثَ يَوْمَ الْجُمُعَةِ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حِينَ كَثُرَ ‏ ‏أَهْلُ الْمَدِينَةِ ‏ ‏وَلَمْ يَكُنْ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُؤَذِّنٌ غَيْرَ وَاحِدٍ وَكَانَ التَّأْذِينُ يَوْمَ الْجُمُعَةِ حِينَ يَجْلِسُ الْإِمَامُ ‏ ‏يَعْنِي عَلَى الْمِنْبَرِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('77be47e4-7396-5451-8fe8-53f7277db939', '5cb5e738-220a-4267-901a-841c834b5d56', '863', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُقَاتِلٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو بَكْرِ بْنُ عُثْمَانَ بْنِ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏وَهُوَ جَالِسٌ عَلَى الْمِنْبَرِ أَذَّنَ الْمُؤَذِّنُ قَالَ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ قَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ قَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏وَأَنَا فَقَالَ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏وَأَنَا فَلَمَّا أَنْ قَضَى التَّأْذِينَ قَالَ يَا أَيُّهَا النَّاسُ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى هَذَا الْمَجْلِسِ حِينَ أَذَّنَ الْمُؤَذِّنُ يَقُولُ مَا سَمِعْتُمْ مِنِّي مِنْ مَقَالَتِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d3e27060-c351-556e-ae73-da1a50f37690', '5cb5e738-220a-4267-901a-841c834b5d56', '864', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏السَّائِبَ بْنَ يَزِيدَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ التَّأْذِينَ الثَّانِيَ يَوْمَ الْجُمُعَةِ أَمَرَ بِهِ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حِينَ كَثُرَ أَهْلُ الْمَسْجِدِ وَكَانَ التَّأْذِينُ يَوْمَ الْجُمُعَةِ حِينَ يَجْلِسُ الْإِمَامُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6fdb0249-a375-5d44-8e2c-9afc9cec1f46', '5cb5e738-220a-4267-901a-841c834b5d56', '865', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُقَاتِلٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏السَّائِبَ بْنَ يَزِيدَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْأَذَانَ يَوْمَ الْجُمُعَةِ كَانَ أَوَّلُهُ حِينَ يَجْلِسُ الْإِمَامُ يَوْمَ الْجُمُعَةِ عَلَى الْمِنْبَرِ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏فَلَمَّا كَانَ فِي خِلَافَةِ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَكَثُرُوا أَمَرَ ‏ ‏عُثْمَانُ ‏ ‏يَوْمَ الْجُمُعَةِ بِالْأَذَانِ الثَّالِثِ فَأُذِّنَ بِهِ عَلَى ‏ ‏الزَّوْرَاءِ ‏ ‏فَثَبَتَ الْأَمْرُ عَلَى ذَلِكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6aea74be-ed95-502c-81ba-2385ce9a2c47', '5cb5e738-220a-4267-901a-841c834b5d56', '866', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَبْدٍ الْقَارِيُّ الْقُرَشِيُّ الْإِسْكَنْدَرَانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو حَازِمِ بْنُ دِينَارٍ ‏ ‏أَنَّ رِجَالًا أَتَوْا ‏ ‏سَهْلَ بْنَ سَعْدٍ السَّاعِدِيَّ ‏ ‏وَقَدْ ‏ ‏امْتَرَوْا ‏ ‏فِي الْمِنْبَرِ مِمَّ عُودُهُ فَسَأَلُوهُ عَنْ ذَلِكَ فَقَالَ وَاللَّهِ إِنِّي لَأَعْرِفُ مِمَّا هُوَ وَلَقَدْ رَأَيْتُهُ أَوَّلَ يَوْمٍ وُضِعَ وَأَوَّلَ يَوْمٍ جَلَسَ عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى فُلَانَةَ امْرَأَةٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَدْ سَمَّاهَا ‏ ‏سَهْلٌ ‏ ‏مُرِي غُلَامَكِ النَّجَّارَ أَنْ يَعْمَلَ لِي أَعْوَادًا أَجْلِسُ عَلَيْهِنَّ إِذَا كَلَّمْتُ النَّاسَ فَأَمَرَتْهُ فَعَمِلَهَا مِنْ ‏ ‏طَرْفَاءِ ‏ ‏الْغَابَةِ ‏ ‏ثُمَّ جَاءَ بِهَا فَأَرْسَلَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَ بِهَا فَوُضِعَتْ هَا هُنَا ثُمَّ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَيْهَا وَكَبَّرَ وَهُوَ عَلَيْهَا ثُمَّ رَكَعَ وَهُوَ عَلَيْهَا ثُمَّ نَزَلَ ‏ ‏الْقَهْقَرَى ‏ ‏فَسَجَدَ فِي أَصْلِ الْمِنْبَرِ ثُمَّ عَادَ فَلَمَّا فَرَغَ أَقْبَلَ عَلَى النَّاسِ فَقَالَ أَيُّهَا النَّاسُ ‏ ‏إِنَّمَا صَنَعْتُ هَذَا لِتَأْتَمُّوا وَلِتَعَلَّمُوا صَلَاتِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1cfe652b-2da1-5023-a619-9467d9dd8ceb', '5cb5e738-220a-4267-901a-841c834b5d56', '867', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي مَرْيَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ أَنَسٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ جِذْعٌ يَقُومُ إِلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا وُضِعَ لَهُ الْمِنْبَرُ ‏ ‏سَمِعْنَا لِلْجِذْعِ مِثْلَ أَصْوَاتِ ‏ ‏الْعِشَارِ ‏ ‏حَتَّى نَزَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَضَعَ يَدَهُ عَلَيْهِ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنِي ‏ ‏حَفْصُ بْنُ عُبَيْدِ اللَّهِ بْنِ أَنَسٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('29da6d8f-5758-5d54-babd-e819934d47ed', '5cb5e738-220a-4267-901a-841c834b5d56', '868', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ بْنُ أَبِي إِيَاسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ عَلَى الْمِنْبَرِ فَقَالَ ‏ ‏مَنْ جَاءَ إِلَى الْجُمُعَةِ فَلْيَغْتَسِلْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('aabfe0d6-b391-5ded-9c17-7a735fb57b8a', '5cb5e738-220a-4267-901a-841c834b5d56', '869', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدُ بْنُ الْحَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ قَائِمًا ثُمَّ يَقْعُدُ ثُمَّ يَقُومُ كَمَا تَفْعَلُونَ الْآنَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6b27853e-cbd4-58f4-94f6-24b2962431b5', '5cb5e738-220a-4267-901a-841c834b5d56', '870', '‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ فَضَالَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ يَسَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏قَالَ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَلَسَ ذَاتَ يَوْمٍ عَلَى الْمِنْبَرِ وَجَلَسْنَا حَوْلَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('60d38ae3-d6c3-5f3c-accd-dbabc7db9d43', '5cb5e738-220a-4267-901a-841c834b5d56', '871', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مَعْمَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ تَغْلِبَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِمَالٍ أَوْ ‏ ‏سَبْيٍ ‏ ‏فَقَسَمَهُ فَأَعْطَى رِجَالًا وَتَرَكَ رِجَالًا فَبَلَغَهُ أَنَّ الَّذِينَ تَرَكَ عَتَبُوا فَحَمِدَ اللَّهَ ثُمَّ أَثْنَى عَلَيْهِ ثُمَّ قَالَ أَمَّا بَعْدُ فَوَاللَّهِ ‏ ‏إِنِّي لَأُعْطِي الرَّجُلَ وَأَدَعُ الرَّجُلَ وَالَّذِي أَدَعُ أَحَبُّ إِلَيَّ مِنْ الَّذِي أُعْطِي وَلَكِنْ أُعْطِي أَقْوَامًا لِمَا أَرَى فِي قُلُوبِهِمْ مِنْ ‏ ‏الْجَزَعِ ‏ ‏وَالْهَلَعِ ‏ ‏وَأَكِلُ أَقْوَامًا إِلَى مَا جَعَلَ اللَّهُ فِي قُلُوبِهِمْ مِنْ الْغِنَى وَالْخَيْرِ فِيهِمْ ‏ ‏عَمْرُو بْنُ تَغْلِبَ ‏ ‏فَوَاللَّهِ مَا أُحِبُّ أَنَّ لِي بِكَلِمَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُمْرَ النَّعَمِ ‏ ‏تَابَعَهُ ‏ ‏يُونُسُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5b381805-44d4-585f-b3a3-b4ab510f4c37', '5cb5e738-220a-4267-901a-841c834b5d56', '872', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ ذَاتَ لَيْلَةٍ مِنْ جَوْفِ اللَّيْلِ فَصَلَّى فِي الْمَسْجِدِ فَصَلَّى رِجَالٌ بِصَلَاتِهِ فَأَصْبَحَ النَّاسُ فَتَحَدَّثُوا فَاجْتَمَعَ أَكْثَرُ مِنْهُمْ فَصَلَّوْا مَعَهُ فَأَصْبَحَ النَّاسُ فَتَحَدَّثُوا فَكَثُرَ أَهْلُ الْمَسْجِدِ مِنْ اللَّيْلَةِ الثَّالِثَةِ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّوْا بِصَلَاتِهِ فَلَمَّا كَانَتْ اللَّيْلَةُ الرَّابِعَةُ عَجَزَ الْمَسْجِدُ عَنْ أَهْلِهِ حَتَّى خَرَجَ لِصَلَاةِ الصُّبْحِ فَلَمَّا قَضَى الْفَجْرَ أَقْبَلَ عَلَى النَّاسِ فَتَشَهَّدَ ثُمَّ قَالَ أَمَّا بَعْدُ ‏ ‏فَإِنَّهُ لَمْ يَخْفَ عَلَيَّ مَكَانُكُمْ لَكِنِّي خَشِيتُ أَنْ تُفْرَضَ عَلَيْكُمْ فَتَعْجِزُوا عَنْهَا ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏تَابَعَهُ ‏ ‏يُونُسُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0caa797e-72e6-57d4-b07e-aa356fc5a517', '5cb5e738-220a-4267-901a-841c834b5d56', '873', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏أَبِي حُمَيْدٍ السَّاعِدِيِّ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ عَشِيَّةً بَعْدَ الصَّلَاةِ فَتَشَهَّدَ وَأَثْنَى عَلَى اللَّهِ بِمَا هُوَ أَهْلُهُ ثُمَّ قَالَ أَمَّا بَعْدُ ‏ ‏تَابَعَهُ ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَأَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي حُمَيْدٍ السَّاعِدِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَمَّا بَعْدُ ‏ ‏تَابَعَهُ ‏ ‏الْعَدَنِيُّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏فِي ‏ ‏أَمَّا بَعْدُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('85529338-a4a8-5f4e-acdc-252ae17aeaf2', '5cb5e738-220a-4267-901a-841c834b5d56', '874', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏الْمِسْوَرِ بْنِ مَخْرَمَةَ ‏ ‏قَالَ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعْتُهُ حِينَ تَشَهَّدَ يَقُولُ ‏ ‏أَمَّا بَعْدُ ‏ ‏تَابَعَهُ ‏ ‏الزُّبَيْدِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3b36e2b2-9ae4-59d3-808f-818617fa1e8b', '5cb5e738-220a-4267-901a-841c834b5d56', '875', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ الْغَسِيلِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏صَعِدَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمِنْبَرَ وَكَانَ آخِرَ مَجْلِسٍ جَلَسَهُ مُتَعَطِّفًا مِلْحَفَةً عَلَى مَنْكِبَيْهِ قَدْ عَصَبَ رَأْسَهُ ‏ ‏بِعِصَابَةٍ ‏ ‏دَسِمَةٍ ‏ ‏فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ أَيُّهَا النَّاسُ إِلَيَّ ‏ ‏فَثَابُوا ‏ ‏إِلَيْهِ ثُمَّ قَالَ أَمَّا بَعْدُ ‏ ‏فَإِنَّ هَذَا الْحَيَّ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يَقِلُّونَ وَيَكْثُرُ النَّاسُ فَمَنْ وَلِيَ شَيْئًا مِنْ أُمَّةِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَطَاعَ أَنْ يَضُرَّ فِيهِ أَحَدًا أَوْ يَنْفَعَ فِيهِ أَحَدًا فَلْيَقْبَلْ مِنْ مُحْسِنِهِمْ وَيَتَجَاوَزْ عَنْ ‏ ‏مُسِيِّهِمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c024fcdc-0c2f-551f-9d2a-2f2dbcc6a18a', '5cb5e738-220a-4267-901a-841c834b5d56', '876', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ خُطْبَتَيْنِ يَقْعُدُ بَيْنَهُمَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('93352c25-f3f0-53f2-b2f8-a21694c3a8c4', '5cb5e738-220a-4267-901a-841c834b5d56', '877', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ يَوْمُ الْجُمُعَةِ وَقَفَتْ الْمَلَائِكَةُ عَلَى بَابِ الْمَسْجِدِ يَكْتُبُونَ الْأَوَّلَ فَالْأَوَّلَ وَمَثَلُ ‏ ‏الْمُهَجِّرِ ‏ ‏كَمَثَلِ الَّذِي ‏ ‏يُهْدِي ‏ ‏بَدَنَةً ‏ ‏ثُمَّ كَالَّذِي ‏ ‏يُهْدِي ‏ ‏بَقَرَةً ثُمَّ كَبْشًا ثُمَّ دَجَاجَةً ثُمَّ بَيْضَةً فَإِذَا خَرَجَ الْإِمَامُ ‏ ‏طَوَوْا ‏ ‏صُحُفَهُمْ وَيَسْتَمِعُونَ الذِّكْرَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('21757b18-55c4-55fa-ba01-e33b0b68c424', '5cb5e738-220a-4267-901a-841c834b5d56', '878', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏رَجُلٌ ‏ ‏وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ النَّاسَ يَوْمَ الْجُمُعَةِ فَقَالَ أَصَلَّيْتَ يَا فُلَانُ قَالَ لَا قَالَ ‏ ‏قُمْ فَارْكَعْ رَكْعَتَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('36659af8-314f-529c-b586-73812437812c', '5cb5e738-220a-4267-901a-841c834b5d56', '879', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏سَمِعَ ‏ ‏جَابِرًا ‏ ‏قَالَ ‏ ‏دَخَلَ رَجُلٌ يَوْمَ الْجُمُعَةِ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ فَقَالَ أَصَلَّيْتَ قَالَ لَا قَالَ ‏ ‏قُمْ فَصَلِّ رَكْعَتَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d648f86e-4041-5b3a-933b-2a081ddef71e', '5cb5e738-220a-4267-901a-841c834b5d56', '880', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَعَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏بَيْنَمَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ يَوْمَ الْجُمُعَةِ إِذْ قَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ هَلَكَ ‏ ‏الْكُرَاعُ ‏ ‏وَهَلَكَ الشَّاءُ فَادْعُ اللَّهَ أَنْ يَسْقِيَنَا فَمَدَّ يَدَيْهِ وَدَعَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('883c771a-dc77-5b63-ad1c-75e349ff47d5', '5cb5e738-220a-4267-901a-841c834b5d56', '881', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَمْرٍو الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَصَابَتْ النَّاسَ سَنَةٌ عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَيْنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ فِي يَوْمِ جُمُعَةٍ قَامَ أَعْرَابِيٌّ فَقَالَ يَا رَسُولَ اللَّهِ هَلَكَ الْمَالُ وَجَاعَ الْعِيَالُ فَادْعُ اللَّهَ لَنَا فَرَفَعَ يَدَيْهِ وَمَا نَرَى فِي السَّمَاءِ ‏ ‏قَزَعَةً ‏ ‏فَوَالَّذِي نَفْسِي بِيَدِهِ مَا وَضَعَهَا حَتَّى ثَارَ السَّحَابُ أَمْثَالَ الْجِبَالِ ثُمَّ لَمْ يَنْزِلْ عَنْ مِنْبَرِهِ حَتَّى رَأَيْتُ الْمَطَرَ ‏ ‏يَتَحَادَرُ ‏ ‏عَلَى لِحْيَتِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمُطِرْنَا يَوْمَنَا ذَلِكَ وَمِنْ الْغَدِ وَبَعْدَ الْغَدِ وَالَّذِي يَلِيهِ حَتَّى الْجُمُعَةِ الْأُخْرَى وَقَامَ ذَلِكَ الْأَعْرَابِيُّ ‏ ‏أَوْ قَالَ غَيْرُهُ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ تَهَدَّمَ الْبِنَاءُ وَغَرِقَ الْمَالُ فَادْعُ اللَّهَ لَنَا فَرَفَعَ يَدَيْهِ فَقَالَ ‏ ‏اللَّهُمَّ ‏ ‏حَوَالَيْنَا ‏ ‏وَلَا عَلَيْنَا فَمَا يُشِيرُ بِيَدِهِ إِلَى نَاحِيَةٍ مِنْ السَّحَابِ إِلَّا انْفَرَجَتْ وَصَارَتْ ‏ ‏الْمَدِينَةُ ‏ ‏مِثْلَ ‏ ‏الْجَوْبَةِ ‏ ‏وَسَالَ الْوَادِي قَنَاةُ شَهْرًا وَلَمْ يَجِئْ أَحَدٌ مِنْ نَاحِيَةٍ إِلَّا حَدَّثَ ‏ ‏بِالْجَوْدِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('48e20ed6-0622-524f-9a4a-1a5ec5041fd7', '5cb5e738-220a-4267-901a-841c834b5d56', '882', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قُلْتَ لِصَاحِبِكَ يَوْمَ الْجُمُعَةِ أَنْصِتْ وَالْإِمَامُ يَخْطُبُ فَقَدْ ‏ ‏لَغَوْتَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9699576c-d01c-58bf-ad8e-381789613f2b', '5cb5e738-220a-4267-901a-841c834b5d56', '883', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ يَوْمَ الْجُمُعَةِ فَقَالَ ‏ ‏فِيهِ سَاعَةٌ لَا يُوَافِقُهَا عَبْدٌ مُسْلِمٌ وَهُوَ قَائِمٌ ‏ ‏يُصَلِّي يَسْأَلُ اللَّهَ تَعَالَى شَيْئًا إِلَّا أَعْطَاهُ إِيَّاهُ وَأَشَارَ بِيَدِهِ يُقَلِّلُهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b51fa1ef-cde2-5923-803e-ec49f39c6d3b', '5cb5e738-220a-4267-901a-841c834b5d56', '884', '‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ نُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ أَقْبَلَتْ عِيرٌ تَحْمِلُ طَعَامًا فَالْتَفَتُوا إِلَيْهَا حَتَّى مَا بَقِيَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا اثْنَا عَشَرَ رَجُلًا ‏ ‏فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏وَإِذَا رَأَوْا تِجَارَةً أَوْ لَهْوًا ‏ ‏انْفَضُّوا ‏ ‏إِلَيْهَا وَتَرَكُوكَ قَائِمًا ‏}', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('df6826ce-5df3-5775-af4e-15455a31ee89', '5cb5e738-220a-4267-901a-841c834b5d56', '885', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي قَبْلَ الظُّهْرِ رَكْعَتَيْنِ وَبَعْدَهَا رَكْعَتَيْنِ وَبَعْدَ الْمَغْرِبِ رَكْعَتَيْنِ فِي بَيْتِهِ وَبَعْدَ الْعِشَاءِ رَكْعَتَيْنِ وَكَانَ لَا ‏ ‏يُصَلِّي بَعْدَ الْجُمُعَةِ حَتَّى يَنْصَرِفَ فَيُصَلِّي رَكْعَتَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bfede358-4c72-5efb-9870-93758ac97612', '5cb5e738-220a-4267-901a-841c834b5d56', '886', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي مَرْيَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو غَسَّانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو حَازِمٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏كَانَتْ فِينَا امْرَأَةٌ تَجْعَلُ عَلَى أَرْبِعَاءَ فِي مَزْرَعَةٍ لَهَا ‏ ‏سِلْقًا ‏ ‏فَكَانَتْ إِذَا كَانَ يَوْمُ جُمُعَةٍ تَنْزِعُ أُصُولَ ‏ ‏السِّلْقِ ‏ ‏فَتَجْعَلُهُ فِي قِدْرٍ ثُمَّ تَجْعَلُ عَلَيْهِ قَبْضَةً مِنْ شَعِيرٍ تَطْحَنُهَا فَتَكُونُ أُصُولُ ‏ ‏السِّلْقِ ‏ ‏عَرْقَهُ ‏ ‏وَكُنَّا نَنْصَرِفُ مِنْ صَلَاةِ الْجُمُعَةِ فَنُسَلِّمُ عَلَيْهَا فَتُقَرِّبُ ذَلِكَ الطَّعَامَ إِلَيْنَا فَنَلْعَقُهُ وَكُنَّا نَتَمَنَّى يَوْمَ الْجُمُعَةِ لِطَعَامِهَا ذَلِكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b798453b-a66c-51aa-a58a-32eb61ec5083', '5cb5e738-220a-4267-901a-841c834b5d56', '887', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَهْلٍ ‏ ‏بِهَذَا وَقَالَ ‏ ‏مَا كُنَّا ‏ ‏نَقِيلُ ‏ ‏وَلَا نَتَغَدَّى إِلَّا بَعْدَ الْجُمُعَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ec5699cf-da27-5341-a27a-1d793d83adc2', '5cb5e738-220a-4267-901a-841c834b5d56', '888', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُقْبَةَ الشَّيْبَانِيُّ الْكُوفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ الْفَزَارِيُّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏كُنَّا نُبَكِّرُ إِلَى الْجُمُعَةِ ثُمَّ ‏ ‏نَقِيلُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a58c326d-1ad0-5990-a995-5eb437074602', '5cb5e738-220a-4267-901a-841c834b5d56', '889', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي مَرْيَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو غَسَّانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو حَازِمٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏كُنَّا نُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجُمُعَةَ ثُمَّ تَكُونُ ‏ ‏الْقَائِلَةُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6c4bee31-2c8d-5358-8bf4-c5b7ec0d8dbe', '5cb5e738-220a-4267-901a-841c834b5d56', '890', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏سَأَلْتُهُ هَلْ صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي صَلَاةَ الْخَوْفِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَالِمٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏غَزَوْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِبَلَ ‏ ‏نَجْدٍ ‏ ‏فَوَازَيْنَا ‏ ‏الْعَدُوَّ فَصَافَفْنَا لَهُمْ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي لَنَا فَقَامَتْ طَائِفَةٌ مَعَهُ تُصَلِّي وَأَقْبَلَتْ طَائِفَةٌ عَلَى الْعَدُوِّ وَرَكَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَنْ مَعَهُ وَسَجَدَ سَجْدَتَيْنِ ثُمَّ انْصَرَفُوا مَكَانَ الطَّائِفَةِ الَّتِي لَمْ تُصَلِّ فَجَاءُوا فَرَكَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهِمْ رَكْعَةً وَسَجَدَ سَجْدَتَيْنِ ثُمَّ سَلَّمَ فَقَامَ كُلُّ وَاحِدٍ مِنْهُمْ فَرَكَعَ لِنَفْسِهِ رَكْعَةً وَسَجَدَ سَجْدَتَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cb238c02-64d9-5a56-b438-2cd2073fa49f', '5cb5e738-220a-4267-901a-841c834b5d56', '891', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ يَحْيَى بْنِ سَعِيدٍ الْقُرَشِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏نَحْوًا مِنْ قَوْلِ ‏ ‏مُجَاهِدٍ ‏ ‏إِذَا اخْتَلَطُوا قِيَامًا وَزَادَ ‏ ‏ابْنُ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنْ كَانُوا أَكْثَرَ مِنْ ذَلِكَ فَلْيُصَلُّوا قِيَامًا وَرُكْبَانًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b811ab35-c0d8-5d37-af02-f73bcc4e2f2d', '5cb5e738-220a-4267-901a-841c834b5d56', '892', '‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏الزُّبَيْدِيِّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَامَ النَّاسُ مَعَهُ فَكَبَّرَ وَكَبَّرُوا مَعَهُ وَرَكَعَ وَرَكَعَ نَاسٌ مِنْهُمْ مَعَهُ ثُمَّ سَجَدَ وَسَجَدُوا مَعَهُ ثُمَّ قَامَ لِلثَّانِيَةِ فَقَامَ الَّذِينَ سَجَدُوا وَحَرَسُوا إِخْوَانَهُمْ وَأَتَتْ الطَّائِفَةُ الْأُخْرَى فَرَكَعُوا وَسَجَدُوا مَعَهُ وَالنَّاسُ كُلُّهُمْ فِي صَلَاةٍ وَلَكِنْ يَحْرُسُ بَعْضُهُمْ بَعْضًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('894c9f2a-115f-5122-8f04-f2661386cd83', '5cb5e738-220a-4267-901a-841c834b5d56', '893', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ جَعْفَرٍ الْبُخَارِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏عُمَرُ ‏ ‏يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏فَجَعَلَ يَسُبُّ كُفَّارَ ‏ ‏قُرَيْشٍ ‏ ‏وَيَقُولُ يَا رَسُولَ اللَّهِ مَا صَلَّيْتُ الْعَصْرَ حَتَّى كَادَتْ الشَّمْسُ أَنْ تَغِيبَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا وَاللَّهِ مَا صَلَّيْتُهَا بَعْدُ قَالَ فَنَزَلَ إِلَى ‏ ‏بُطْحَانَ ‏ ‏فَتَوَضَّأَ وَصَلَّى الْعَصْرَ بَعْدَ مَا غَابَتْ الشَّمْسُ ثُمَّ صَلَّى الْمَغْرِبَ بَعْدَهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fa5a9451-a52e-527a-98bb-de5efcc5f5f8', '5cb5e738-220a-4267-901a-841c834b5d56', '894', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَسْمَاءَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جُوَيْرِيَةُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَنَا لَمَّا رَجَعَ مِنْ الْأَحْزَابِ ‏ ‏لَا يُصَلِّيَنَّ أَحَدٌ الْعَصْرَ إِلَّا فِي ‏ ‏بَنِي قُرَيْظَةَ ‏ ‏فَأَدْرَكَ بَعْضَهُمْ الْعَصْرُ فِي الطَّرِيقِ فَقَالَ بَعْضُهُمْ لَا نُصَلِّي حَتَّى نَأْتِيَهَا وَقَالَ بَعْضُهُمْ بَلْ نُصَلِّي لَمْ يُرَدْ مِنَّا ذَلِكَ فَذُكِرَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يُعَنِّفْ وَاحِدًا مِنْهُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0bad88a2-23fd-5735-b3eb-69b97d9e080e', '5cb5e738-220a-4267-901a-841c834b5d56', '895', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏وَثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الصُّبْحَ ‏ ‏بِغَلَسٍ ‏ ‏ثُمَّ رَكِبَ فَقَالَ ‏ ‏اللَّهُ أَكْبَرُ خَرِبَتْ ‏ ‏خَيْبَرُ ‏ ‏إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ ‏ { ‏فَسَاءَ صَبَاحُ الْمُنْذَرِينَ ‏} ‏فَخَرَجُوا يَسْعَوْنَ فِي السِّكَكِ وَيَقُولُونَ ‏ ‏مُحَمَّدٌ ‏ ‏وَالْخَمِيسُ ‏ ‏قَالَ وَالْخَمِيسُ الْجَيْشُ ‏ ‏فَظَهَرَ عَلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَتَلَ الْمُقَاتِلَةَ وَسَبَى الذَّرَارِيَّ فَصَارَتْ ‏ ‏صَفِيَّةُ ‏ ‏لِدِحْيَةَ الْكَلْبِيِّ ‏ ‏وَصَارَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ تَزَوَّجَهَا وَجَعَلَ صَدَاقَهَا عِتْقَهَا ‏ ‏فَقَالَ ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏لِثَابِتٍ ‏ ‏يَا ‏ ‏أَبَا مُحَمَّدٍ ‏ ‏أَنْتَ سَأَلْتَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏مَا أَمْهَرَهَا قَالَ أَمْهَرَهَا نَفْسَهَا فَتَبَسَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('58c4ced1-fec8-5474-83f2-51cd0ef38aac', '5cb5e738-220a-4267-901a-841c834b5d56', '896', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏أَخَذَ ‏ ‏عُمَرُ ‏ ‏جُبَّةً ‏ ‏مِنْ إِسْتَبْرَقٍ تُبَاعُ فِي السُّوقِ فَأَخَذَهَا فَأَتَى بِهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ابْتَعْ هَذِهِ تَجَمَّلْ بِهَا لِلْعِيدِ وَالْوُفُودِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا هَذِهِ لِبَاسُ مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ فَلَبِثَ ‏ ‏عُمَرُ ‏ ‏مَا شَاءَ اللَّهُ أَنْ يَلْبَثَ ثُمَّ أَرْسَلَ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجُبَّةِ ‏ ‏دِيبَاجٍ ‏ ‏فَأَقْبَلَ بِهَا ‏ ‏عُمَرُ ‏ ‏فَأَتَى بِهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّكَ قُلْتَ إِنَّمَا هَذِهِ لِبَاسُ مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ وَأَرْسَلْتَ إِلَيَّ بِهَذِهِ ‏ ‏الْجُبَّةِ ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَبِيعُهَا أَوْ تُصِيبُ بِهَا حَاجَتَكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e4676fac-7646-51a5-8de5-0cb75d9367c0', '5cb5e738-220a-4267-901a-841c834b5d56', '897', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَمْرٌو ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ عَبْدِ الرَّحْمَنِ الْأَسَدِيَّ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدِي ‏ ‏جَارِيَتَانِ تُغَنِّيَانِ بِغِنَاءِ ‏ ‏بُعَاثَ ‏ ‏فَاضْطَجَعَ عَلَى الْفِرَاشِ وَحَوَّلَ وَجْهَهُ وَدَخَلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَانْتَهَرَنِي وَقَالَ مِزْمَارَةُ الشَّيْطَانِ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَقْبَلَ عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ ‏ ‏دَعْهُمَا فَلَمَّا غَفَلَ غَمَزْتُهُمَا فَخَرَجَتَا وَكَانَ يَوْمَ عِيدٍ يَلْعَبُ ‏ ‏السُّودَانُ ‏ ‏بِالدَّرَقِ وَالْحِرَابِ فَإِمَّا سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِمَّا قَالَ تَشْتَهِينَ تَنْظُرِينَ فَقُلْتُ نَعَمْ فَأَقَامَنِي وَرَاءَهُ خَدِّي عَلَى خَدِّهِ وَهُوَ يَقُولُ دُونَكُمْ يَا ‏ ‏بَنِي أَرْفِدَةَ ‏ ‏حَتَّى إِذَا مَلِلْتُ قَالَ حَسْبُكِ قُلْتُ نَعَمْ قَالَ فَاذْهَبِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5f56e677-808d-5465-aeae-7b093f25d9df', '5cb5e738-220a-4267-901a-841c834b5d56', '898', '‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏زُبَيْدٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ فَقَالَ ‏ ‏إِنَّ أَوَّلَ مَا نَبْدَأُ مِنْ يَوْمِنَا هَذَا أَنْ نُصَلِّيَ ثُمَّ نَرْجِعَ فَنَنْحَرَ فَمَنْ فَعَلَ فَقَدْ أَصَابَ سُنَّتَنَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('28fad00c-9205-5985-ab61-fec9c69cf7d9', '5cb5e738-220a-4267-901a-841c834b5d56', '899', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏دَخَلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعِنْدِي ‏ ‏جَارِيَتَانِ مِنْ جَوَارِي ‏ ‏الْأَنْصَارِ ‏ ‏تُغَنِّيَانِ بِمَا تَقَاوَلَتْ ‏ ‏الْأَنْصَارُ ‏ ‏يَوْمَ ‏ ‏بُعَاثَ ‏ ‏قَالَتْ وَلَيْسَتَا بِمُغَنِّيَتَيْنِ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَمَزَامِيرُ الشَّيْطَانِ فِي بَيْتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَذَلِكَ فِي يَوْمِ عِيدٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏إِنَّ ‏ ‏لِكُلِّ قَوْمٍ عِيدًا وَهَذَا عِيدُنَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('aba16797-f553-5509-8856-b0aba8f52f61', '5cb5e738-220a-4267-901a-841c834b5d56', '900', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي بَكْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَغْدُو يَوْمَ الْفِطْرِ حَتَّى يَأْكُلَ تَمَرَاتٍ ‏ ‏وَقَالَ ‏ ‏مُرَجَّأُ بْنُ رَجَاءٍ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَنَسٌ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيَأْكُلُهُنَّ وِتْرًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('90e48193-35da-586f-8327-331a7b60ebea', '5cb5e738-220a-4267-901a-841c834b5d56', '901', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ذَبَحَ قَبْلَ الصَّلَاةِ فَلْيُعِدْ فَقَامَ رَجُلٌ فَقَالَ هَذَا يَوْمٌ يُشْتَهَى فِيهِ اللَّحْمُ وَذَكَرَ مِنْ جِيرَانِهِ فَكَأَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَّقَهُ قَالَ وَعِنْدِي ‏ ‏جَذَعَةٌ ‏ ‏أَحَبُّ إِلَيَّ مِنْ شَاتَيْ لَحْمٍ فَرَخَّصَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا أَدْرِي أَبَلَغَتْ الرُّخْصَةُ مَنْ سِوَاهُ أَمْ لَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('524a9d47-8568-5129-8505-8d2e5537408e', '5cb5e738-220a-4267-901a-841c834b5d56', '902', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏خَطَبَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْأَضْحَى بَعْدَ الصَّلَاةِ فَقَالَ ‏ ‏مَنْ صَلَّى صَلَاتَنَا ‏ ‏وَنَسَكَ ‏ ‏نُسُكَنَا فَقَدْ أَصَابَ النُّسُكَ وَمَنْ ‏ ‏نَسَكَ ‏ ‏قَبْلَ الصَّلَاةِ فَإِنَّهُ قَبْلَ الصَّلَاةِ وَلَا ‏ ‏نُسُكَ ‏ ‏لَهُ فَقَالَ ‏ ‏أَبُو بُرْدَةَ بْنُ نِيَارٍ ‏ ‏خَالُ ‏ ‏الْبَرَاءِ ‏ ‏يَا رَسُولَ اللَّهِ فَإِنِّي نَسَكْتُ شَاتِي قَبْلَ الصَّلَاةِ وَعَرَفْتُ أَنَّ الْيَوْمَ يَوْمُ أَكْلٍ وَشُرْبٍ وَأَحْبَبْتُ أَنْ تَكُونَ شَاتِي أَوَّلَ مَا يُذْبَحُ فِي بَيْتِي فَذَبَحْتُ شَاتِي وَتَغَدَّيْتُ قَبْلَ أَنْ آتِيَ الصَّلَاةَ قَالَ شَاتُكَ شَاةُ لَحْمٍ قَالَ يَا رَسُولَ اللَّهِ فَإِنَّ عِنْدَنَا ‏ ‏عَنَاقًا ‏ ‏لَنَا ‏ ‏جَذَعَةً ‏ ‏هِيَ أَحَبُّ إِلَيَّ مِنْ شَاتَيْنِ أَفَتَجْزِي عَنِّي قَالَ نَعَمْ وَلَنْ تَجْزِيَ عَنْ أَحَدٍ بَعْدَكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6ea81614-16ec-526e-8b96-4599ba6bc563', '5cb5e738-220a-4267-901a-841c834b5d56', '903', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي مَرْيَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي سَرْحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ يَوْمَ الْفِطْرِ وَالْأَضْحَى إِلَى الْمُصَلَّى فَأَوَّلُ شَيْءٍ يَبْدَأُ بِهِ الصَّلَاةُ ثُمَّ يَنْصَرِفُ فَيَقُومُ مُقَابِلَ النَّاسِ وَالنَّاسُ جُلُوسٌ عَلَى صُفُوفِهِمْ فَيَعِظُهُمْ وَيُوصِيهِمْ وَيَأْمُرُهُمْ فَإِنْ كَانَ يُرِيدُ أَنْ يَقْطَعَ بَعْثًا قَطَعَهُ أَوْ يَأْمُرَ بِشَيْءٍ أَمَرَ بِهِ ثُمَّ يَنْصَرِفُ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَلَمْ يَزَلْ النَّاسُ عَلَى ذَلِكَ حَتَّى خَرَجْتُ مَعَ ‏ ‏مَرْوَانَ ‏ ‏وَهُوَ أَمِيرُ ‏ ‏الْمَدِينَةِ ‏ ‏فِي أَضْحًى أَوْ فِطْرٍ فَلَمَّا أَتَيْنَا الْمُصَلَّى إِذَا مِنْبَرٌ بَنَاهُ ‏ ‏كَثِيرُ بْنُ الصَّلْتِ ‏ ‏فَإِذَا ‏ ‏مَرْوَانُ ‏ ‏يُرِيدُ أَنْ يَرْتَقِيَهُ قَبْلَ أَنْ يُصَلِّيَ ‏ ‏فَجَبَذْتُ ‏ ‏بِثَوْبِهِ فَجَبَذَنِي فَارْتَفَعَ فَخَطَبَ قَبْلَ الصَّلَاةِ فَقُلْتُ لَهُ غَيَّرْتُمْ وَاللَّهِ فَقَالَ ‏ ‏أَبَا سَعِيدٍ ‏ ‏قَدْ ذَهَبَ مَا تَعْلَمُ فَقُلْتُ مَا أَعْلَمُ وَاللَّهِ خَيْرٌ مِمَّا لَا أَعْلَمُ فَقَالَ إِنَّ النَّاسَ لَمْ يَكُونُوا يَجْلِسُونَ لَنَا بَعْدَ الصَّلَاةِ فَجَعَلْتُهَا قَبْلَ الصَّلَاةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bc23b2c7-56aa-53ea-8b10-5ca56fd6adb7', '5cb5e738-220a-4267-901a-841c834b5d56', '904', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي فِي الْأَضْحَى وَالْفِطْرِ ثُمَّ يَخْطُبُ بَعْدَ الصَّلَاةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('aa8768ea-2c48-5f75-a7c9-68b3e25503d6', '5cb5e738-220a-4267-901a-841c834b5d56', '905', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏أَنَّ ‏ ‏ابْنَ جُرَيْجٍ ‏ ‏أَخْبَرَهُمْ قَالَ أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُهُ يَقُولُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ يَوْمَ الْفِطْرِ فَبَدَأَ بِالصَّلَاةِ قَبْلَ الْخُطْبَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9f7a51d3-6c12-5c61-a172-136a8947eaad', '5cb5e738-220a-4267-901a-841c834b5d56', '906', '‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَرْسَلَ إِلَى ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏فِي أَوَّلِ مَا بُويِعَ لَهُ ‏ ‏إِنَّهُ لَمْ يَكُنْ يُؤَذَّنُ بِالصَّلَاةِ يَوْمَ الْفِطْرِ إِنَّمَا الْخُطْبَةُ بَعْدَ الصَّلَاةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fed211b7-2cfc-5010-9386-6799073b4eee', '5cb5e738-220a-4267-901a-841c834b5d56', '907', '‏ ‏و أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَعَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَا ‏ ‏لَمْ يَكُنْ يُؤَذَّنُ يَوْمَ الْفِطْرِ وَلَا يَوْمَ الْأَضْحَى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dcd82d1f-161d-52c2-af38-3c706f6b4136', '5cb5e738-220a-4267-901a-841c834b5d56', '908', '‏ ‏وَعَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُهُ يَقُولُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ ‏ ‏فَبَدَأَ بِالصَّلَاةِ ثُمَّ خَطَبَ النَّاسَ بَعْدُ فَلَمَّا فَرَغَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ فَأَتَى النِّسَاءَ فَذَكَّرَهُنَّ وَهُوَ يَتَوَكَّأُ عَلَى يَدِ ‏ ‏بِلَالٍ ‏ ‏وَبِلَالٌ ‏ ‏بَاسِطٌ ثَوْبَهُ يُلْقِي فِيهِ النِّسَاءُ صَدَقَةً ‏ ‏قُلْتُ ‏ ‏لِعَطَاءٍ ‏ ‏أَتَرَى حَقًّا عَلَى الْإِمَامِ الْآنَ أَنْ يَأْتِيَ النِّسَاءَ فَيُذَكِّرَهُنَّ حِينَ يَفْرُغُ قَالَ ‏ ‏إِنَّ ذَلِكَ لَحَقٌّ عَلَيْهِمْ وَمَا لَهُمْ أَنْ لَا يَفْعَلُوا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4f42d24b-9785-50d3-b6fa-b69155b99a5a', '5cb5e738-220a-4267-901a-841c834b5d56', '909', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْحَسَنُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏شَهِدْتُ الْعِيدَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏ ‏فَكُلُّهُمْ كَانُوا يُصَلُّونَ قَبْلَ الْخُطْبَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fbe10dc7-1cef-53b7-9981-a61fa17fbe24', '5cb5e738-220a-4267-901a-841c834b5d56', '910', '‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏يُصَلُّونَ الْعِيدَيْنِ قَبْلَ الْخُطْبَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('53c37328-7197-50b5-a3e2-ebcb3e9ac157', '5cb5e738-220a-4267-901a-841c834b5d56', '911', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى يَوْمَ الْفِطْرِ رَكْعَتَيْنِ لَمْ يُصَلِّ قَبْلَهَا وَلَا بَعْدَهَا ثُمَّ أَتَى النِّسَاءَ وَمَعَهُ ‏ ‏بِلَالٌ ‏ ‏فَأَمَرَهُنَّ بِالصَّدَقَةِ فَجَعَلْنَ يُلْقِينَ تُلْقِي الْمَرْأَةُ ‏ ‏خُرْصَهَا ‏ ‏وَسِخَابَهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f73f28a8-1343-57cf-a03f-86d42215c8b0', '5cb5e738-220a-4267-901a-841c834b5d56', '912', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُبَيْدٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَوَّلَ مَا نَبْدَأُ فِي يَوْمِنَا هَذَا أَنْ نُصَلِّيَ ثُمَّ نَرْجِعَ ‏ ‏فَنَنْحَرَ ‏ ‏فَمَنْ فَعَلَ ذَلِكَ فَقَدْ أَصَابَ سُنَّتَنَا وَمَنْ ‏ ‏نَحَرَ ‏ ‏قَبْلَ الصَّلَاةِ فَإِنَّمَا هُوَ لَحْمٌ قَدَّمَهُ لِأَهْلِهِ لَيْسَ مِنْ النُّسْكِ فِي شَيْءٍ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يُقَالُ لَهُ ‏ ‏أَبُو بُرْدَةَ بْنُ نِيَارٍ ‏ ‏يَا رَسُولَ اللَّهِ ذَبَحْتُ وَعِنْدِي ‏ ‏جَذَعَةٌ ‏ ‏خَيْرٌ مِنْ ‏ ‏مُسِنَّةٍ ‏ ‏فَقَالَ اجْعَلْهُ مَكَانَهُ وَلَنْ تُوفِيَ أَوْ تَجْزِيَ عَنْ أَحَدٍ بَعْدَكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('44e7e49d-6d92-5713-af1a-f566e10204e8', '5cb5e738-220a-4267-901a-841c834b5d56', '913', '‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّاءُ بْنُ يَحْيَى أَبُو السُّكَيْنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُحَارِبِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سُوقَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏حِينَ أَصَابَهُ سِنَانُ الرُّمْحِ فِي أَخْمَصِ قَدَمِهِ فَلَزِقَتْ قَدَمُهُ بِالرِّكَابِ فَنَزَلْتُ فَنَزَعْتُهَا وَذَلِكَ ‏ ‏بِمِنًى ‏ ‏فَبَلَغَ ‏ ‏الْحَجَّاجَ ‏ ‏فَجَعَلَ يَعُودُهُ فَقَالَ ‏ ‏الْحَجَّاجُ ‏ ‏لَوْ نَعْلَمُ مَنْ أَصَابَكَ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنْتَ أَصَبْتَنِي قَالَ وَكَيْفَ قَالَ حَمَلْتَ السِّلَاحَ فِي يَوْمٍ لَمْ يَكُنْ يُحْمَلُ فِيهِ وَأَدْخَلْتَ السِّلَاحَ ‏ ‏الْحَرَمَ ‏ ‏وَلَمْ يَكُنْ السِّلَاحُ يُدْخَلُ ‏ ‏الْحَرَمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('25d96d8e-0cd3-5653-a1cb-f60b588e9a40', '5cb5e738-220a-4267-901a-841c834b5d56', '914', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ يَعْقُوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِسْحَاقُ بْنُ سَعِيدِ بْنِ عَمْرِو بْنِ سَعِيدِ بْنِ الْعَاصِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏الْحَجَّاجُ ‏ ‏عَلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏وَأَنَا عِنْدَهُ فَقَالَ كَيْفَ هُوَ فَقَالَ صَالِحٌ فَقَالَ مَنْ أَصَابَكَ قَالَ ‏ ‏أَصَابَنِي مَنْ أَمَرَ بِحَمْلِ السِّلَاحِ فِي يَوْمٍ لَا يَحِلُّ فِيهِ حَمْلُهُ ‏ ‏يَعْنِي ‏ ‏الْحَجَّاجَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('735a1aa0-7837-5f78-90f4-b655ffa8d84c', '5cb5e738-220a-4267-901a-841c834b5d56', '915', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ ‏ ‏خَطَبَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏قَالَ ‏ ‏إِنَّ أَوَّلَ مَا نَبْدَأُ بِهِ فِي يَوْمِنَا هَذَا أَنْ نُصَلِّيَ ثُمَّ نَرْجِعَ ‏ ‏فَنَنْحَرَ ‏ ‏فَمَنْ فَعَلَ ذَلِكَ فَقَدْ أَصَابَ سُنَّتَنَا وَمَنْ ذَبَحَ قَبْلَ أَنْ يُصَلِّيَ فَإِنَّمَا هُوَ لَحْمٌ عَجَّلَهُ لِأَهْلِهِ لَيْسَ مِنْ النُّسُكِ فِي شَيْءٍ فَقَامَ خَالِي ‏ ‏أَبُو بُرْدَةَ بْنُ نِيَارٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَنَا ذَبَحْتُ قَبْلَ أَنْ أُصَلِّيَ وَعِنْدِي ‏ ‏جَذَعَةٌ ‏ ‏خَيْرٌ مِنْ ‏ ‏مُسِنَّةٍ ‏ ‏قَالَ اجْعَلْهَا مَكَانَهَا ‏ ‏أَوْ قَالَ اذْبَحْهَا ‏ ‏وَلَنْ تَجْزِيَ ‏ ‏جَذَعَةٌ ‏ ‏عَنْ أَحَدٍ بَعْدَكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f39ec299-f065-5512-8947-4916966fb4ac', '5cb5e738-220a-4267-901a-841c834b5d56', '916', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَرْعَرَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا الْعَمَلُ فِي أَيَّامٍ أَفْضَلَ مِنْهَا فِي هَذِهِ قَالُوا وَلَا الْجِهَادُ قَالَ وَلَا الْجِهَادُ إِلَّا رَجُلٌ خَرَجَ يُخَاطِرُ بِنَفْسِهِ وَمَالِهِ فَلَمْ يَرْجِعْ بِشَيْءٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('91f57571-44c8-5bba-84b4-f60bc3645b0e', '5cb5e738-220a-4267-901a-841c834b5d56', '917', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الثَّقَفِيُّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏وَنَحْنُ غَادِيَانِ مِنْ ‏ ‏مِنًى ‏ ‏إِلَى ‏ ‏عَرَفَاتٍ ‏ ‏عَنْ التَّلْبِيَةِ كَيْفَ كُنْتُمْ تَصْنَعُونَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ ‏ ‏يُلَبِّي الْمُلَبِّي لَا يُنْكَرُ عَلَيْهِ وَيُكَبِّرُ الْمُكَبِّرُ فَلَا يُنْكَرُ عَلَيْهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('002f8e1a-ec81-55b0-8098-ad3ccb896089', '5cb5e738-220a-4267-901a-841c834b5d56', '918', '‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَفْصٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنْ ‏ ‏أُمِّ عَطِيَّةَ ‏ ‏قَالَتْ ‏ ‏كُنَّا نُؤْمَرُ أَنْ نَخْرُجَ يَوْمَ الْعِيدِ حَتَّى نُخْرِجَ الْبِكْرَ مِنْ خِدْرِهَا حَتَّى نُخْرِجَ الْحُيَّضَ فَيَكُنَّ خَلْفَ النَّاسِ فَيُكَبِّرْنَ بِتَكْبِيرِهِمْ وَيَدْعُونَ بِدُعَائِهِمْ يَرْجُونَ بَرَكَةَ ذَلِكَ الْيَوْمِ وَطُهْرَتَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('299b0918-1fff-5084-b67e-871e03b5aa19', '5cb5e738-220a-4267-901a-841c834b5d56', '919', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ تُرْكَزُ الْحَرْبَةُ قُدَّامَهُ يَوْمَ الْفِطْرِ وَالنَّحْرِ ثُمَّ ‏ ‏يُصَلِّي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1f364991-2516-5d71-8fe7-8b00c1aab4f3', '5cb5e738-220a-4267-901a-841c834b5d56', '920', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ الْحِزَامِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَمْرٍو الْأَوْزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْدُو إِلَى الْمُصَلَّى ‏ ‏وَالْعَنَزَةُ ‏ ‏بَيْنَ يَدَيْهِ تُحْمَلُ وَتُنْصَبُ بِالْمُصَلَّى بَيْنَ يَدَيْهِ فَيُصَلِّي إِلَيْهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f684c04c-fbc2-5da4-bede-61704a7ac019', '5cb5e738-220a-4267-901a-841c834b5d56', '921', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الْوَهَّابِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أُمِّ عَطِيَّةَ ‏ ‏قَالَتْ ‏ ‏أَمَرَنَا نَبِيُّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَنْ نُخْرِجَ ‏ ‏الْعَوَاتِقَ ‏ ‏وَذَوَاتِ ‏ ‏الْخُدُورِ ‏ ‏وَعَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏بِنَحْوِهِ وَزَادَ فِي حَدِيثِ ‏ ‏حَفْصَةَ ‏ ‏قَالَ ‏ ‏أَوْ قَالَتْ ‏ ‏الْعَوَاتِقَ ‏ ‏وَذَوَاتِ ‏ ‏الْخُدُورِ ‏ ‏وَيَعْتَزِلْنَ الْحُيَّضُ الْمُصَلَّى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9873f536-ac4e-58e2-a1d3-30e9e877a38c', '5cb5e738-220a-4267-901a-841c834b5d56', '922', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَبَّاسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَابِسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ فِطْرٍ ‏ ‏أَوْ أَضْحَى ‏ ‏فَصَلَّى ثُمَّ خَطَبَ ثُمَّ أَتَى النِّسَاءَ فَوَعَظَهُنَّ وَذَكَّرَهُنَّ وَأَمَرَهُنَّ بِالصَّدَقَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('05e9665a-f65e-51be-a296-32381793c07c', '5cb5e738-220a-4267-901a-841c834b5d56', '923', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ ‏ ‏خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ أَضْحًى إِلَى ‏ ‏الْبَقِيعِ ‏ ‏فَصَلَّى رَكْعَتَيْنِ ثُمَّ أَقْبَلَ عَلَيْنَا بِوَجْهِهِ وَقَالَ ‏ ‏إِنَّ أَوَّلَ ‏ ‏نُسُكِنَا ‏ ‏فِي يَوْمِنَا هَذَا أَنْ نَبْدَأَ بِالصَّلَاةِ ثُمَّ نَرْجِعَ ‏ ‏فَنَنْحَرَ ‏ ‏فَمَنْ فَعَلَ ذَلِكَ فَقَدْ وَافَقَ سُنَّتَنَا وَمَنْ ذَبَحَ قَبْلَ ذَلِكَ فَإِنَّمَا هُوَ شَيْءٌ عَجَّلَهُ لِأَهْلِهِ لَيْسَ مِنْ ‏ ‏النُّسُكِ ‏ ‏فِي شَيْءٍ فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي ذَبَحْتُ وَعِنْدِي ‏ ‏جَذَعَةٌ ‏ ‏خَيْرٌ مِنْ ‏ ‏مُسِنَّةٍ ‏ ‏قَالَ اذْبَحْهَا وَلَا تَفِي عَنْ أَحَدٍ بَعْدَكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7810ebf2-f7f2-52fe-81b7-523ad28bd63f', '5cb5e738-220a-4267-901a-841c834b5d56', '924', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَابِسٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قِيلَ لَهُ أَشَهِدْتَ الْعِيدَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَعَمْ وَلَوْلَا مَكَانِي مِنْ الصِّغَرِ مَا شَهِدْتُهُ حَتَّى أَتَى الْعَلَمَ الَّذِي عِنْدَ دَارِ ‏ ‏كَثِيرِ بْنِ الصَّلْتِ ‏ ‏فَصَلَّى ثُمَّ خَطَبَ ثُمَّ أَتَى النِّسَاءَ وَمَعَهُ ‏ ‏بِلَالٌ ‏ ‏فَوَعَظَهُنَّ وَذَكَّرَهُنَّ وَأَمَرَهُنَّ بِالصَّدَقَةِ فَرَأَيْتُهُنَّ يَهْوِينَ بِأَيْدِيهِنَّ يَقْذِفْنَهُ فِي ثَوْبِ ‏ ‏بِلَالٍ ‏ ‏ثُمَّ انْطَلَقَ هُوَ ‏ ‏وَبِلَالٌ ‏ ‏إِلَى بَيْتِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('07f36459-1bea-5c51-94f2-cf6d44d8d925', '5cb5e738-220a-4267-901a-841c834b5d56', '925', '‏ ‏حَدَّثَنِي ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ بْنِ نَصْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُهُ يَقُولُ ‏ ‏قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفِطْرِ ‏ ‏فَصَلَّى فَبَدَأَ بِالصَّلَاةِ ثُمَّ خَطَبَ فَلَمَّا فَرَغَ نَزَلَ فَأَتَى النِّسَاءَ فَذَكَّرَهُنَّ وَهُوَ يَتَوَكَّأُ عَلَى يَدِ ‏ ‏بِلَالٍ ‏ ‏وَبِلَالٌ ‏ ‏بَاسِطٌ ثَوْبَهُ يُلْقِي فِيهِ النِّسَاءُ الصَّدَقَةَ ‏ ‏قُلْتُ ‏ ‏لِعَطَاءٍ ‏ ‏زَكَاةَ يَوْمِ الْفِطْرِ قَالَ ‏ ‏لَا وَلَكِنْ صَدَقَةً يَتَصَدَّقْنَ حِينَئِذٍ تُلْقِي ‏ ‏فَتَخَهَا ‏ ‏وَيُلْقِينَ قُلْتُ أَتُرَى حَقًّا عَلَى الْإِمَامِ ذَلِكَ وَيُذَكِّرُهُنَّ قَالَ إِنَّهُ لَحَقٌّ عَلَيْهِمْ وَمَا لَهُمْ لَا يَفْعَلُونَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e2858957-a102-55e2-bf4c-c2f44be5acd5', '5cb5e738-220a-4267-901a-841c834b5d56', '926', '‏ ‏قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَأَخْبَرَنِي ‏ ‏الْحَسَنُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏شَهِدْتُ الْفِطْرَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏ ‏يُصَلُّونَهَا قَبْلَ الْخُطْبَةِ ثُمَّ يُخْطَبُ بَعْدُ خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنِّي أَنْظُرُ إِلَيْهِ حِينَ يُجَلِّسُ بِيَدِهِ ثُمَّ أَقْبَلَ يَشُقُّهُمْ حَتَّى جَاءَ النِّسَاءَ مَعَهُ ‏ ‏بِلَالٌ ‏ ‏فَقَالَ ‏ { ‏يَا أَيُّهَا النَّبِيُّ إِذَا جَاءَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ ‏} ‏الْآيَةَ ثُمَّ قَالَ حِينَ فَرَغَ مِنْهَا ‏ ‏آنْتُنَّ عَلَى ذَلِكِ قَالَتْ امْرَأَةٌ وَاحِدَةٌ مِنْهُنَّ لَمْ يُجِبْهُ غَيْرُهَا نَعَمْ ‏ ‏لَا يَدْرِي حَسَنٌ مَنْ هِيَ ‏ ‏قَالَ فَتَصَدَّقْنَ فَبَسَطَ ‏ ‏بِلَالٌ ‏ ‏ثَوْبَهُ ثُمَّ قَالَ هَلُمَّ لَكُنَّ فِدَاءٌ أَبِي وَأُمِّي فَيُلْقِينَ ‏ ‏الْفَتَخَ ‏ ‏وَالْخَوَاتِيمَ فِي ثَوْبِ ‏ ‏بِلَالٍ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏الْفَتَخُ ‏ ‏الْخَوَاتِيمُ الْعِظَامُ كَانَتْ فِي الْجَاهِلِيَّةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('be744d2c-cc3d-57ce-9fb0-629c09b712cc', '5cb5e738-220a-4267-901a-841c834b5d56', '927', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ سِيرِينَ ‏ ‏قَالَتْ ‏ ‏كُنَّا نَمْنَعُ جَوَارِيَنَا أَنْ يَخْرُجْنَ يَوْمَ الْعِيدِ فَجَاءَتْ امْرَأَةٌ فَنَزَلَتْ قَصْرَ ‏ ‏بَنِي خَلَفٍ ‏ ‏فَأَتَيْتُهَا فَحَدَّثَتْ أَنَّ زَوْجَ أُخْتِهَا غَزَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثِنْتَيْ عَشْرَةَ غَزْوَةً فَكَانَتْ أُخْتُهَا مَعَهُ فِي سِتِّ غَزَوَاتٍ فَقَالَتْ فَكُنَّا نَقُومُ عَلَى الْمَرْضَى وَنُدَاوِي الْكَلْمَى فَقَالَتْ يَا رَسُولَ اللَّهِ أَعَلَى إِحْدَانَا بَأْسٌ إِذَا لَمْ يَكُنْ لَهَا جِلْبَابٌ أَنْ لَا تَخْرُجَ فَقَالَ لِتُلْبِسْهَا صَاحِبَتُهَا مِنْ جِلْبَابِهَا فَلْيَشْهَدْنَ الْخَيْرَ وَدَعْوَةَ الْمُؤْمِنِينَ قَالَتْ ‏ ‏حَفْصَةُ ‏ ‏فَلَمَّا قَدِمَتْ ‏ ‏أُمُّ عَطِيَّةَ ‏ ‏أَتَيْتُهَا فَسَأَلْتُهَا أَسَمِعْتِ فِي كَذَا وَكَذَا قَالَتْ نَعَمْ بِأَبِي وَقَلَّمَا ذَكَرَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا قَالَتْ بِأَبِي قَالَ ‏ ‏لِيَخْرُجْ ‏ ‏الْعَوَاتِقُ ‏ ‏ذَوَاتُ ‏ ‏الْخُدُورِ ‏ ‏أَوْ قَالَ ‏ ‏الْعَوَاتِقُ ‏ ‏وَذَوَاتُ ‏ ‏الْخُدُورِ ‏ ‏شَكَّ ‏ ‏أَيُّوبُ ‏ ‏وَالْحُيَّضُ وَيَعْتَزِلُ الْحُيَّضُ الْمُصَلَّى وَلْيَشْهَدْنَ الْخَيْرَ وَدَعْوَةَ الْمُؤْمِنِينَ قَالَتْ فَقُلْتُ لَهَا الْحُيَّضُ قَالَتْ نَعَمْ أَلَيْسَ الْحَائِضُ تَشْهَدُ ‏ ‏عَرَفَاتٍ ‏ ‏وَتَشْهَدُ كَذَا وَتَشْهَدُ كَذَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('14734506-3950-5d0a-8316-a8999d386d21', '5cb5e738-220a-4267-901a-841c834b5d56', '928', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ قَالَتْ ‏ ‏أُمُّ عَطِيَّةَ ‏ ‏أُمِرْنَا أَنْ نَخْرُجَ ‏ ‏فَنُخْرِجَ الْحُيَّضَ ‏ ‏وَالْعَوَاتِقَ ‏ ‏وَذَوَاتِ ‏ ‏الْخُدُورِ ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏أَوْ ‏ ‏الْعَوَاتِقَ ‏ ‏ذَوَاتِ ‏ ‏الْخُدُورِ ‏ ‏فَأَمَّا الْحُيَّضُ فَيَشْهَدْنَ جَمَاعَةَ الْمُسْلِمِينَ وَدَعْوَتَهُمْ وَيَعْتَزِلْنَ مُصَلَّاهُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('67b8091f-8418-50eb-8e52-5372261889e3', '5cb5e738-220a-4267-901a-841c834b5d56', '929', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏كَثِيرُ بْنُ فَرْقَدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنْحَرُ أَوْ يَذْبَحُ بِالْمُصَلَّى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a747c906-ad92-52a9-9f58-6cc38bd4134a', '5cb5e738-220a-4267-901a-841c834b5d56', '930', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ الْمُعْتَمِرِ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏بَعْدَ الصَّلَاةِ فَقَالَ ‏ ‏مَنْ صَلَّى صَلَاتَنَا ‏ ‏وَنَسَكَ ‏ ‏نُسْكَنَا ‏ ‏فَقَدْ أَصَابَ ‏ ‏النُّسُكَ ‏ ‏وَمَنْ نَسَكَ قَبْلَ الصَّلَاةِ فَتِلْكَ شَاةُ لَحْمٍ فَقَامَ ‏ ‏أَبُو بُرْدَةَ بْنُ نِيَارٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ وَاللَّهِ لَقَدْ ‏ ‏نَسَكْتُ ‏ ‏قَبْلَ أَنْ أَخْرُجَ إِلَى الصَّلَاةِ وَعَرَفْتُ أَنَّ الْيَوْمَ يَوْمُ أَكْلٍ وَشُرْبٍ فَتَعَجَّلْتُ وَأَكَلْتُ وَأَطْعَمْتُ أَهْلِي وَجِيرَانِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِلْكَ شَاةُ لَحْمٍ قَالَ فَإِنَّ عِنْدِي ‏ ‏عَنَاقَ ‏ ‏جَذَعَةٍ ‏ ‏هِيَ خَيْرٌ مِنْ شَاتَيْ لَحْمٍ فَهَلْ تَجْزِي عَنِّي قَالَ نَعَمْ وَلَنْ تَجْزِيَ عَنْ أَحَدٍ بَعْدَكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fc631f53-2d6f-5040-82d3-84e98292cd40', '5cb5e738-220a-4267-901a-841c834b5d56', '931', '‏ ‏حَدَّثَنَا ‏ ‏حَامِدُ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏أَنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى يَوْمَ النَّحْرِ ثُمَّ خَطَبَ فَأَمَرَ مَنْ ذَبَحَ قَبْلَ الصَّلَاةِ أَنْ يُعِيدَ ذَبْحَهُ فَقَامَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ جِيرَانٌ لِي إِمَّا قَالَ بِهِمْ خَصَاصَةٌ وَإِمَّا قَالَ بِهِمْ فَقْرٌ وَإِنِّي ذَبَحْتُ قَبْلَ الصَّلَاةِ وَعِنْدِي عَنَاقٌ لِي أَحَبُّ إِلَيَّ مِنْ شَاتَيْ لَحْمٍ فَرَخَّصَ لَهُ فِيهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e94f8087-348a-5fb9-a7b8-dff4f5f3f4f0', '5cb5e738-220a-4267-901a-841c834b5d56', '932', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏جُنْدَبٍ ‏ ‏قَالَ ‏ ‏صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ النَّحْرِ ثُمَّ خَطَبَ ثُمَّ ذَبَحَ فَقَالَ ‏ ‏مَنْ ذَبَحَ قَبْلَ أَنْ يُصَلِّيَ فَلْيَذْبَحْ أُخْرَى مَكَانَهَا وَمَنْ لَمْ يَذْبَحْ فَلْيَذْبَحْ بِاسْمِ اللَّهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('52b3a612-919e-5df5-ad90-588239fff5d5', '5cb5e738-220a-4267-901a-841c834b5d56', '933', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ هُوَ ابْنُ سَلَامٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو تُمَيْلَةَ يَحْيَى بْنُ وَاضِحٍ ‏ ‏عَنْ ‏ ‏فُلَيْحِ بْنِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ يَوْمُ عِيدٍ خَالَفَ الطَّرِيقَ ‏ ‏تَابَعَهُ ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏فُلَيْحٍ ‏ ‏وَقَالَ ‏ ‏مُحَمَّدُ بْنُ الصَّلْتِ ‏ ‏عَنْ ‏ ‏فُلَيْحٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَحَدِيثُ ‏ ‏جَابِرٍ ‏ ‏أَصَحُّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ee95775f-3a68-53ce-b8a5-a79fdf930a18', '5cb5e738-220a-4267-901a-841c834b5d56', '934', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏دَخَلَ عَلَيْهَا وَعِنْدَهَا ‏ ‏جَارِيَتَانِ فِي أَيَّامِ ‏ ‏مِنَى ‏ ‏تُدَفِّفَانِ وَتَضْرِبَانِ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَغَشٍّ بِثَوْبِهِ ‏ ‏فَانْتَهَرَهُمَا ‏ ‏أَبُو بَكْرٍ ‏ ‏فَكَشَفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ وَجْهِهِ فَقَالَ ‏ ‏دَعْهُمَا يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَإِنَّهَا أَيَّامُ عِيدٍ وَتِلْكَ الْأَيَّامُ أَيَّامُ ‏ ‏مِنًى ‏ ‏وَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتُرُنِي وَأَنَا أَنْظُرُ إِلَى ‏ ‏الْحَبَشَةِ ‏ ‏وَهُمْ يَلْعَبُونَ فِي الْمَسْجِدِ فَزَجَرَهُمْ ‏ ‏عُمَرُ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُمْ أَمْنًا ‏ ‏بَنِي أَرْفِدَةَ ‏ ‏يَعْنِي مِنْ الْأَمْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('072e9770-bcc5-52e0-8dfc-ef75c936bc97', '5cb5e738-220a-4267-901a-841c834b5d56', '935', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ يَوْمَ الْفِطْرِ فَصَلَّى رَكْعَتَيْنِ لَمْ يُصَلِّ قَبْلَهَا وَلَا بَعْدَهَا وَمَعَهُ ‏ ‏بِلَالٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('73b66f89-1ab5-57fe-a25a-47958d52f637', '5cb5e738-220a-4267-901a-841c834b5d56', '936', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏وَعَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَلَاةِ اللَّيْلِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى فَإِذَا خَشِيَ أَحَدُكُمْ الصُّبْحَ صَلَّى رَكْعَةً وَاحِدَةً تُوتِرُ لَهُ مَا قَدْ صَلَّى ‏ ‏وَعَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يُسَلِّمُ بَيْنَ الرَّكْعَةِ وَالرَّكْعَتَيْنِ فِي الْوِتْرِ حَتَّى يَأْمُرَ بِبَعْضِ حَاجَتِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d588b649-efdf-5e8a-b1f0-84320211c814', '5cb5e738-220a-4267-901a-841c834b5d56', '937', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏مَخْرَمَةَ بْنِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ بَاتَ عِنْدَ ‏ ‏مَيْمُونَةَ ‏ ‏وَهِيَ خَالَتُهُ فَاضْطَجَعْتُ فِي عَرْضِ وِسَادَةٍ ‏ ‏وَاضْطَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَهْلُهُ فِي طُولِهَا فَنَامَ حَتَّى انْتَصَفَ اللَّيْلُ أَوْ قَرِيبًا مِنْهُ فَاسْتَيْقَظَ يَمْسَحُ النَّوْمَ عَنْ وَجْهِهِ ثُمَّ قَرَأَ عَشْرَ آيَاتٍ مِنْ آلِ ‏ ‏عِمْرَانَ ‏ ‏ثُمَّ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏شَنٍّ ‏ ‏مُعَلَّقَةٍ فَتَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ قَامَ ‏ ‏يُصَلِّي فَصَنَعْتُ مِثْلَهُ فَقُمْتُ إِلَى جَنْبهِ فَوَضَعَ يَدَهُ الْيُمْنَى عَلَى رَأْسِي وَأَخَذَ بِأُذُنِي ‏ ‏يَفْتِلُهَا ‏ ‏ثُمَّ صَلَّى رَكْعَتَيْنِ ثُمَّ رَكْعَتَيْنِ ثُمَّ رَكْعَتَيْنِ ثُمَّ رَكْعَتَيْنِ ثُمَّ رَكْعَتَيْنِ ثُمَّ رَكْعَتَيْنِ ثُمَّ أَوْتَرَ ثُمَّ اضْطَجَعَ حَتَّى جَاءَهُ الْمُؤَذِّنُ فَقَامَ فَصَلَّى رَكْعَتَيْنِ ثُمَّ خَرَجَ فَصَلَّى الصُّبْحَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3747f3c0-4dd8-50a2-ad8c-a4bc0386c824', '5cb5e738-220a-4267-901a-841c834b5d56', '938', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ الْقَاسِمِ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى فَإِذَا أَرَدْتَ أَنْ تَنْصَرِفَ فَارْكَعْ رَكْعَةً تُوتِرُ لَكَ مَا صَلَّيْتَ ‏ ‏قَالَ ‏ ‏الْقَاسِمُ ‏ ‏وَرَأَيْنَا أُنَاسًا مُنْذُ أَدْرَكْنَا يُوتِرُونَ بِثَلَاثٍ وَإِنَّ كُلًّا لَوَاسِعٌ أَرْجُو أَنْ لَا يَكُونَ بِشَيْءٍ مِنْهُ بَأْسٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6385ee02-9a4f-539a-8d5f-36154fd7e36d', '5cb5e738-220a-4267-901a-841c834b5d56', '939', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُرْوَةُ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي إِحْدَى عَشْرَةَ رَكْعَةً كَانَتْ تِلْكَ صَلَاتَهُ تَعْنِي بِاللَّيْلِ فَيَسْجُدُ السَّجْدَةَ مِنْ ذَلِكَ قَدْرَ مَا يَقْرَأُ أَحَدُكُمْ خَمْسِينَ آيَةً قَبْلَ أَنْ يَرْفَعَ رَأْسَهُ وَيَرْكَعُ رَكْعَتَيْنِ قَبْلَ صَلَاةِ الْفَجْرِ ثُمَّ يَضْطَجِعُ عَلَى شِقِّهِ الْأَيْمَنِ حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ لِلصَّلَاةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2c1c9f6e-37fe-55a3-ba1d-77320049653b', '5cb5e738-220a-4267-901a-841c834b5d56', '940', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏قَالَ قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَرَأَيْتَ الرَّكْعَتَيْنِ قَبْلَ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏أُطِيلُ فِيهِمَا الْقِرَاءَةَ فَقَالَ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ مَثْنَى مَثْنَى وَيُوتِرُ بِرَكْعَةٍ وَيُصَلِّي الرَّكْعَتَيْنِ قَبْلَ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏وَكَأَنَّ الْأَذَانَ بِأُذُنَيْهِ قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَيْ سُرْعَةً ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f512f102-ee0b-5e1b-9edd-feb230045ecc', '5cb5e738-220a-4267-901a-841c834b5d56', '941', '‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَفْصٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُسْلِمٌ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُلَّ اللَّيْلِ أَوْتَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَانْتَهَى وِتْرُهُ إِلَى السَّحَرِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('efef16e0-ecc6-57a7-a330-70cb29287068', '5cb5e738-220a-4267-901a-841c834b5d56', '942', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَأَنَا رَاقِدَةٌ مُعْتَرِضَةً عَلَى فِرَاشِهِ فَإِذَا أَرَادَ أَنْ يُوتِرَ أَيْقَظَنِي فَأَوْتَرْتُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
